def prune(obj):
    """Drop empty values, recursively: what is left is what the records actually say."""
    if isinstance(obj, dict):
        out = {k: v for k, v in ((k, prune(v)) for k, v in obj.items()) if v not in (None, "", [], {})}
        return out or None
    if isinstance(obj, list):
        return [v for v in (prune(v) for v in obj) if v not in (None, "", [], {})] or None
    return obj


def from_context(ctx, sid):
    """The supplier's and the product's records from `DataPackage.negotiation_context`, non-empty only."""
    out = {}
    if supplier := prune((ctx or {}).get("suppliers", {}).get(sid)):
        out["db_supplier"] = supplier
    if product := prune((ctx or {}).get("product", {}).get("parts")):
        out["db_product"] = product
    return out


def _rows(rows, skip=()):
    return "\n".join(
        "  "
        + json.dumps(
            {k: v for k, v in r.items() if v not in (None, "") and k not in skip}, ensure_ascii=False, default=str
        )
        for r in rows
    )


def render(d):
    """The dossier as text, newest first, for one language-model read."""
    out = [f"SUPPLIER {d['supplier_id']}"]
    for title, key in (
        ("Master data", "supplier"),
        ("Company (filed accounts, credit index: higher is worse)", "intel"),
        ("Contract", "contract"),
        ("Contract clauses", "clauses"),
        ("Scorecards, newest first", "scorecards"),
        ("Past negotiations with us (asked vs settled %)", "history"),
        ("Our price conditions", "price_conditions"),
        ("Quotes for these parts (all suppliers)", "quotes"),
        ("Should-cost estimates (no margin)", "should_cost"),
        ("Cost drivers of the part (index series, weight)", "cost_drivers"),
        ("Who else can make the part", "sourcing"),
        ("Parts", "parts"),
        ("News", "news"),
        ("Quality last 12 months", "quality"),
        ("How we paid them last 12 months", "payments"),
        ("Demand forecast", "forecast"),
    ):
        if d.get(key):
            out.append(f"{title}:\n{_rows(d[key])}")
    if d.get("correspondence"):
        out.append("Correspondence, call and meeting notes (newest first):")
        for r in d["correspondence"]:
            out.append(
                f"  [{r.get('date')} {r.get('kind') or ''} {r['id']}] {r.get('subject') or r.get('headline') or ''}: "
                f"{r.get('text', '')}"
            )
    if d.get("case_facts"):
        out.append(
            f"Facts only this case has:\n  {json.dumps(d['case_facts'], ensure_ascii=False, default=str)[:3000]}"
        )
    if d.get("cash_signals"):
        out.append(f"Cash signals found: {', '.join(d['cash_signals'])}")
    for title, key, limit in (
        ("Database: this supplier (master, intel, contracts, history, deliveries, invoices)", "db_supplier", 6000),
        ("Database: the product (should-cost, price history, quotes, RFQs, indices)", "db_product", 4000),
    ):
        if d.get(key):
            out.append(f"{title}:\n  {json.dumps(d[key], ensure_ascii=False, default=str)[:limit]}")
    return "\n".join(out)

