"""Term-sheet helpers: a valid sheet, the options of a term, which way a term helps the supplier."""

import json
from datetime import date

from ..cost import closing_terms

# Which way each term is worth more to the supplier: +1 higher, -1 lower (index_clause: having one).
SUPPLIER_LIKES = {
    "payment_days": -1, "effective_date": -1, "contract_months": +1, "volume_per_year": +1,
    "lead_time_days": +1, "ppm_commitment": +1, "chargeback_eur_per_complaint": -1, "tooling_eur": +1,
    "incoterm": -1, "index_clause": +1,
}  # fmt: skip
INCOTERM_RANK = {"EXW": 0, "FCA": 1, "DAP": 2}  # the supplier carries more freight up the list
COVERAGE = ("contract_months", "volume_per_year")  # terms that decide how much of the need is covered


def key(value):
    """A hashable, order-free form of a term value (index clauses are dicts)."""
    return json.dumps(value, sort_keys=True, default=str)


def same(a, b):
    """Two term sheets equal up to a cent."""
    if set(a) != set(b):
        return False
    for k in a:
        x, y = a[k], b[k]
        if isinstance(x, int | float) and isinstance(y, int | float) and not isinstance(x, bool):
            if abs(x - y) > 0.005:
                return False
        elif key(x) != key(y):
            return False
    return True


def distance(a, b):
    """How far an option is from a value: numbers by difference, anything else 0 if equal else 1."""
    if isinstance(a, int | float) and isinstance(b, int | float) and not isinstance(a, bool):
        return abs(a - b)
    return 0 if key(a) == key(b) else 1


def _as_date(v):
    try:
        return date.fromisoformat(str(v)[:10])
    except ValueError:
        return None


def snap_option(options, value):
    """The allowed option equal to `value` (the option object itself), else the nearest one."""
    if not options:
        return value
    for o in options:
        if key(o) == key(value) or (
            isinstance(o, int | float) and isinstance(value, int | float) and not isinstance(value, bool) and o == value
        ):
            return o
    if isinstance(value, int | float) and all(isinstance(o, int | float) for o in options):
        return min(options, key=lambda o: (abs(o - value), o))
    if isinstance(value, str) and (d := _as_date(value)) and all(isinstance(o, str) and _as_date(o) for o in options):
        return min(options, key=lambda o: abs((_as_date(o) - d).days))
    if isinstance(value, dict):  # an index clause that is not an option: the same series, else none
        same_series = [o for o in options if isinstance(o, dict) and o.get("series") == value.get("series")]
        if same_series:
            return min(same_series, key=lambda o: abs(o.get("deadband_pct", 0) - value.get("deadband_pct", 0)))
    return None if None in options else options[0]


def options(case, field, std=None):
    """The values a term may take: the case's options, else the supplier's standard value."""
    opts = (case.get("term_options") or {}).get(field)
    if opts:
        return list(opts)
    value = (std or {}).get(field, (case.get("fixed_terms") or {}).get(field))
    return [value] if value is not None or field == "index_clause" else []


def complete(case, terms, std=None):
    """A valid term sheet: exactly the negotiable fields; what `terms` leaves out from the supplier's
    standard terms, the fixed terms and the buyer's plan; every value snapped to an allowed option.
    A field without options keeps the supplier's standard value (api.md, Terms)."""
    std = std or {}
    base = closing_terms(case, {"unit_price": None}, std)
    freight = (case.get("buyer") or {}).get("freight_eur_per_unit") or {}
    out = {}
    for field in case["negotiable"]:
        if field in terms:
            value = terms[field]
        elif field == "incoterm" and not std.get("incoterm") and freight:
            value = min(freight, key=freight.get)  # when asking, ask for the cheapest freight
        else:
            value = base.get(field)
        if field == "unit_price":
            out[field] = round(float(value), 2) if value is not None else None
            continue
        opts = (case.get("term_options") or {}).get(field)
        if opts:
            value = snap_option(opts, value)
        elif field in std:
            value = std[field]
        out[field] = value
    return out


def order(field, values):
    """Values from least to most attractive for the supplier."""
    if field == "index_clause":
        return sorted(values, key=lambda v: (v is not None, -(v or {}).get("deadband_pct", 0)))
    if field == "incoterm":
        return sorted(values, key=lambda v: -INCOTERM_RANK.get(v, 1))
    if not all(isinstance(v, int | float | str) for v in values):
        return list(values)
    return sorted(values, reverse=SUPPLIER_LIKES.get(field, 1) < 0)


def step(case, field, value, std=None, toward_supplier=True, n=1):
    """The option `n` steps from `value` toward what the supplier (or we) prefer, or None."""
    vals = order(field, options(case, field, std))
    keys = [key(v) for v in vals]
    if key(value) not in keys or len(vals) < 2:
        return None
    i = keys.index(key(value)) + (n if toward_supplier else -n)
    return vals[i] if 0 <= i < len(vals) else None


def liked(field, opts):
    """The option the supplier likes best."""
    return order(field, opts)[-1] if opts else None


def committed_units(case, terms, std=None):
    t = closing_terms(case, terms, std)
    months = t.get("contract_months") or 0
    years = min(months / 12 if months else 1.0, case["buyer"]["horizon_years"])
    return (t.get("volume_per_year") or 0) * years


def uncovered_units(case, terms, std=None):
    """Need the terms leave uncovered over the horizon (R12.2, R11.17)."""
    b = case["buyer"]
    t = closing_terms(case, terms, std)
    months = t.get("contract_months") or 0
    years = min(months / 12 if months else 1.0, b["horizon_years"])
    covered = min(t.get("volume_per_year") or 0, b["need_per_year"]) * years
    return max(0.0, b["need_per_year"] * b["horizon_years"] - covered)

"""Our estimate of the supplier (section 2): its full cost and its cost of money.

The estimate only prices the supplier's health - the margin charge that C carries in strategic and
bottleneck cases (R2.3) - and the shared surplus of a give (R6.2). Calibration (R2.1): its own cost
breakdown if it sent one, else should-cost / FULL_COST_K, else its opening price / 1.10. Neither too
high (a high floor made BuyerAgent stop pushing, P01) nor too low (P02: the arena charged EUR 124,110
for a price BuyerAgent's low estimate saw as free).
"""

import logging
import re
from dataclasses import dataclass, field

from ..cost import RELATIONSHIP_GOALS, closing_terms, total_cost

log = logging.getLogger("arena")

FULL_COST_K = 1.02  # full cost = should-cost / 1.02: fits the arena's relationship charge over 31 deals
OPENING_K = 1.10  # no data at all: full cost = opening price / 1.10
CASH_PREMIUM = 0.06  # R2.2: a supplier short of cash values money 6 points more than we do
RATE_BOUNDS = (0.03, 0.40)  # R2.2: a revealed rate is clamped to this


@dataclass
class Estimate:
    full_cost: float | None = None
    point: float | None = None  # the cost estimate itself (should-cost), for the fair price (R4.1)
    source: str = "none"  # breakdown | should-cost | opening | none
    rate: float = 0.08  # its cost of money per year
    usual_rate: float = 0.08
    opening: dict = field(default_factory=dict)  # its opening terms: standard terms the PDF left out

    def supplier(self, case, std=None):
        """The `supplier` argument of `total_cost` - only where the goal carries a margin charge."""
        if self.full_cost is None or (case.get("buyer") or {}).get("category_goal") not in RELATIONSHIP_GOALS:
            return None
        return self.as_supplier(case, std)

    def as_supplier(self, case, std=None):
        standard = closing_terms(case, {}, {**{k: v for k, v in self.opening.items() if k != "unit_price"}, **(std or {})})
        return {
            "standard": standard,
            "interest_rate": self.rate,
            "usual_rate": self.usual_rate,
            "full_cost": self.full_cost or 0.0,
        }


def breakdown_cost(text):
    """Full cost per unit from a cost-breakdown XLSX (as `docs.read_document` reads it): the sum of
    its EUR elements without margin and totals."""
    total, found = 0.0, False
    for line in (text or "").splitlines():
        cells = [c.strip() for c in line.split("|")]
        if len(cells) < 2 or re.search(r"margin|profit|ebit|unit price|total|sum|price|share|%", cells[0], re.I):
            continue
        try:
            total += float(cells[1])
            found = True
        except ValueError:
            continue
    return round(total, 2) if found and total > 0 else None


def should_cost(package, case):
    """The data's should-cost for the case's parts (summed over a bundle), or None."""
    costs = []
    for part in case.get("parts") or []:
        num = str(part).split(":", 1)[-1]
        fact = (case.get("facts") or {}).get(f"cost:{num}") or (package.lookup(f"cost:{num}") if package else None)
        value = (fact or {}).get("unit_cost")
        if value is None and package is not None:
            try:
                rows = package.query(
                    "SELECT unit_cost FROM should_cost WHERE part_id = ? ORDER BY estimate_date DESC", (part,)
                )
            except Exception:
                rows = []
            value = rows[0]["unit_cost"] if rows else None
        if value is None:
            return None
        costs.append(float(value))
    return sum(costs) if costs else None


def estimate(case, package, events=None, opening=None, cash_short=False, revealed_rate=None):
    """The estimate for one supplier thread. `events`: the thread so far (a cost-breakdown XLSX in it
    wins); `opening`: its opening term sheet; `revealed_rate`: its own price of payment days (R12.4)."""
    rate = float((case.get("buyer") or {}).get("interest_rate") or 0.08)
    usual = rate
    if cash_short:
        rate += CASH_PREMIUM
    if revealed_rate:
        rate = min(max(revealed_rate, RATE_BOUNDS[0]), RATE_BOUNDS[1])
    opening = dict(opening or {})
    for m in reversed(events or []):
        if m.get("from") == "buyer":
            continue
        for att in m.get("attachments") or []:
            if "breakdown" in (att.get("name") or "").lower() and att.get("text"):
                if (fc := breakdown_cost(att["text"])) is not None:
                    return Estimate(fc, fc, "breakdown", rate, usual, opening)
    if (sc := should_cost(package, case)) is not None:
        return Estimate(round(sc / FULL_COST_K, 2), sc, "should-cost", rate, usual, opening)
    price = opening.get("unit_price")
    if price:
        return Estimate(round(price / OPENING_K, 2), None, "opening", rate, usual, opening)
    return Estimate(None, None, "none", rate, usual, opening)


def cost(case, terms, std, est):
    """C of terms for us: the published cost function, with the margin charge where the goal has one."""
    try:
        return total_cost(case, terms, std, est.supplier(case, std) if est else None)
    except Exception as e:  # a sheet we cannot price is never the cheapest
        log.debug("cost failed: %s", e)
        return float("inf")


def plain_cost(case, terms, std):
    """C without the margin charge (what the alternative is compared against)."""
    try:
        return total_cost(case, terms, std)
    except Exception:
        return float("inf")

"""R13.8: the unit price at which a package costs exactly a target C.

Without the supplier's margin charge C is linear in the price: p = (target - C(0)) / (C(1) - C(0)).
With it, C is convex in the price - falling down to the cheapest price, rising below it (a squeezed
supplier costs more than the price saves). The cheapest price is found by golden-section search
between 0.5x and 1.5x the supplier's price, and the target is solved by bisection on the side ABOVE
it: a price below the cheapest one costs more and leaves the supplier weaker.

Prices are whole cents, so a package's C can miss the target by up to half a cent per committed
unit (P08: 189,600 units, up to EUR 948); `tolerance` gives that bound.
"""

import math

from ..cost import total_cost
from .terms import committed_units

GOLDEN = (5**0.5 - 1) / 2


def _c(case, terms, std, supplier, p):
    return total_cost(case, {**terms, "unit_price": p}, std, supplier)


def tolerance(case, terms, std=None):
    """How close to a target C a whole-cent price can get: EUR 1, or half a cent per unit."""
    return max(1.0, 0.005 * committed_units(case, terms, std))


def cheapest_price(case, terms, std, supplier, hint):
    """The price at which these terms cost us least once the margin charge counts (C is convex in
    the price): golden-section search between 0.5x and 1.5x `hint`."""
    if supplier is None:
        return 0.5 * hint
    lo, hi = 0.5 * hint, 1.5 * hint
    for _ in range(80):
        a, b = hi - GOLDEN * (hi - lo), lo + GOLDEN * (hi - lo)
        if _c(case, terms, std, supplier, a) <= _c(case, terms, std, supplier, b):
            hi = b
        else:
            lo = a
    return (lo + hi) / 2


def price_for(case, terms, std, target, supplier=None, hint=None):
    """The whole-cent unit price at which `terms` cost `target`, or None if no price does.
    `hint`: the supplier's price (the search window with a margin charge)."""
    if supplier is None:
        c0 = _c(case, terms, std, None, 0.0)
        c1 = _c(case, terms, std, None, 1.0)
        if not (math.isfinite(c0) and math.isfinite(c1)) or c1 <= c0:
            return None
        p = (target - c0) / (c1 - c0)
        return round(p, 2) if p > 0 else None
    hint = hint or terms.get("unit_price") or 1.0
    low = cheapest_price(case, terms, std, supplier, hint)
    if _c(case, terms, std, supplier, low) > target + tolerance(case, terms, std):
        return None  # out of reach: even the cheapest price costs more
    high = 1.5 * hint
    if _c(case, terms, std, supplier, high) <= target:
        return round(high, 2)
    for _ in range(60):
        mid = (low + high) / 2
        if _c(case, terms, std, supplier, mid) < target:
            low = mid
        else:
            high = mid
    p = round((low + high) / 2, 2)
    # whole cents: take the cent closer to the target, never one below the cheapest price
    best = min((p - 0.01, p, p + 0.01), key=lambda q: abs(_c(case, terms, std, supplier, q) - target))
    return round(max(best, round(cheapest_price(case, terms, std, supplier, hint), 2)), 2)


def c_min_price(case, terms, std, supplier, lo, hi):
    """The price in [lo, hi] at which `terms` cost us least (with a margin charge the bottom of the
    convex curve; without one, `lo`) - R4.2: never anchor under the price at which C stops falling."""
    if supplier is None:
        return lo
    p = cheapest_price(case, terms, std, supplier, (lo + hi) / 2 if hi > lo else hi)
    return min(max(p, lo), hi)

"""What each negotiable term is worth in EUR (R12.3), and what the supplier itself charges for it
(R12.4). Ported from TeamAgent's `team/levers.py`.

For a term sheet every negotiable field is moved to each allowed option, and the price by 1 %; the
change in C is the lever's value in EUR and per committed unit (`price_equiv`). Only levers worth at
least MIN_LEVER_SHARE of C are asked for (coverage always counts): suppliers price every demand in, at
3-7x its value for faster lead time or chargebacks. With the supplier's revealed prices a lever counts
only if it saves us more than the supplier charges; on a tie (within EUR 1) the option closest to its
own value wins - no stricter ask than needed.
"""

import itertools
import statistics

from ..cost import closing_terms, must_haves_ok, total_cost
from .terms import COVERAGE, committed_units, distance, key

PRICE_STEP_PCT = 1.0
MIN_LEVER_SHARE = 0.003  # R12.3: ask only for levers worth at least 0.3 % of C


def revealed_slopes(case, messages, extra=None):
    """What the supplier charges for a term, from its own sheet pairs that differ in one field only:
    {field: relative price change per unit of the field} for numbers (payment days, lead time, ppm),
    {(field, from, to): price ratio} for the rest. Median per field. `extra`: more packages per
    message (prose alternatives, R13.6), as [[terms, ...], ...] aligned with `messages`."""
    fields = [f for f in case.get("negotiable", []) if f != "unit_price"]
    seen = {}
    for n, m in enumerate(messages):
        if m.get("from") == "buyer":
            continue
        sheets = [ts.get("terms") or {} for ts in m.get("term_sheets") or []]
        if extra and n < len(extra):
            sheets += list(extra[n] or [])
        sheets = [t for t in sheets if t.get("unit_price")]
        for a, b in itertools.combinations(sheets, 2):
            diff = [f for f in fields if key(a.get(f)) != key(b.get(f))]
            if len(diff) != 1 or diff[0] not in a or diff[0] not in b:
                continue
            f, (va, vb), (pa, pb) = diff[0], (a[diff[0]], b[diff[0]]), (a["unit_price"], b["unit_price"])
            if all(isinstance(v, int | float) and not isinstance(v, bool) for v in (va, vb)):
                if va != vb:
                    seen.setdefault(f, []).append((pb / pa - 1) / (vb - va))
            else:
                seen.setdefault((f, key(va), key(vb)), []).append(pb / pa)
                seen.setdefault((f, key(vb), key(va)), []).append(pa / pb)
    return {k: statistics.median(v) for k, v in seen.items()}


def revealed_rate(slopes):
    """The supplier's cost of money from its own payment-days slope (R2.2): slope x 360, or None.
    Paying later costs it money, so its price rises with the days: a positive slope."""
    s = slopes.get("payment_days")
    return s * 360 if s and s > 0 else None


def lever_table(case, terms, std=None, supplier=None, slopes=None):
    """Every single-field move from `terms`, cheapest for us first:
    [{field, current, option, c, delta_eur, price_equiv, must_haves_ok}]; delta_eur < 0 saves money.
    With `slopes`, a move also carries the price the supplier would charge for it."""
    base_terms = closing_terms(case, terms, std)
    if base_terms.get("unit_price") is None:
        return []
    base = total_cost(case, terms, std, supplier)
    units = committed_units(case, terms, std) or 1.0
    rows = []

    def priced(field, option):
        p, cur = base_terms["unit_price"], base_terms.get(field)
        if not slopes or field == "unit_price":
            return p
        if field in slopes and isinstance(option, int | float) and isinstance(cur, int | float):
            return round(p * (1 + slopes[field] * (option - cur)), 2)
        return round(p * slopes.get((field, key(cur), key(option)), 1.0), 2)

    def add(field, option):
        moved = {**terms, field: option}
        if field != "unit_price":
            moved["unit_price"] = priced(field, option)
        c = total_cost(case, moved, std, supplier)
        rows.append(
            {
                "field": field,
                "current": base_terms.get(field),
                "option": option,
                "c": c,
                "delta_eur": round(c - base, 2),
                "price_equiv": round((c - base) / units, 4),
                "must_haves_ok": must_haves_ok(case, moved, std),
            }
        )

    for field in case.get("negotiable", []):
        if field == "unit_price":
            add(field, round(base_terms["unit_price"] * (1 - PRICE_STEP_PCT / 100), 2))
            continue
        for option in (case.get("term_options") or {}).get(field) or []:
            if key(option) != key(base_terms.get(field)):
                add(field, option)
    return sorted(rows, key=lambda r: r["delta_eur"])


def best_levers(case, terms, std=None, supplier=None, slopes=None):
    """{field: lever row}: the best option per non-price field that saves at least MIN_LEVER_SHARE of
    C (coverage always counts) and keeps the must-haves. With revealed prices, only levers that save
    more than the supplier charges; ties within EUR 1 go to the option closest to its own value."""
    rows, base_c = {}, total_cost(case, terms, std, supplier)
    for row in lever_table(case, terms, std, supplier, slopes):
        big = -row["delta_eur"] >= MIN_LEVER_SHARE * base_c or row["field"] in COVERAGE
        if row["field"] != "unit_price" and row["must_haves_ok"] and row["delta_eur"] < 0 and big:
            rows.setdefault(row["field"], []).append(row)
    best = {}
    for f, rs in rows.items():
        top = min(r["delta_eur"] for r in rs)
        ties = [r for r in rs if r["delta_eur"] - top < 1]
        best[f] = min(ties, key=lambda r: distance(r["option"], r["current"]))
    return best


def label(value):
    if isinstance(value, dict):
        return f"index {value.get('series')} share {value.get('material_share')} band {value.get('deadband_pct')}%"
    return "none" if value is None else str(value)

"""The supplier's offers stated in words (R13.6, R11.1).

`prose_alternatives` reads the "Alternatively, with <terms>: EUR <price> per unit" lines suppliers
write next to their term sheet - in English and German (Alternativ, mit Zahlungsziel / Lieferzeit /
Preisgleitklausel ...) - for payment days, effective date, lead time, volume, contract months, ppm,
chargeback, Incoterm and the index clause. A line whose index clause cannot be pinned to one of the
case's options is skipped. These packages feed the accept ladder's offer-back (R12.11, R12.13), the
revealed lock (R13.5) and the revealed slopes (R12.4).

`prose_offers` is the looser reading DualAgent's analyst did by code: any sentence with offer words
and a price, with the terms it names.
"""

import re

from .terms import key

LEAD = r"(?:alternatively|alternativ|or alternatively|oder alternativ)"
ALT_RE = re.compile(
    LEAD + r",?\s+(?:with|mit|bei)\s+(?P<cond>.+?):\s*(?:€|EUR)?\s?(?P<price>\d[\d.,]*)\s*(?:€|EUR)?\s*"
    r"(?:per unit|per piece|per pc|pro stück|je stück|pro einheit|per kg|pro kg|/\s*stück)",
    re.I,
)
PAYMENT_RE = re.compile(
    r"(?:zahlungsziel|zahlung(?:sbedingung)?(?:en)?|payment(?: terms?)?(?: of| in| at)?)\s+(?:von\s+)?(\d{1,3})\s+"
    r"(?:days|tage|tagen)|(\d{1,3})\s+(?:days|tage)\s+(?:net|netto)",
    re.I,
)
LEAD_RE = re.compile(r"(?:lieferzeit|lead[- ]time)(?: of| von)?\s+(\d{1,3})\s+(?:days|tage|tagen)", re.I)
MONTHS_RE = re.compile(r"\b(\d{1,2})[- ](?:months?|monate?n?)\b", re.I)
VOLUME_RE = re.compile(
    r"\b(\d{1,3}(?:[.,]\d{3})+|\d{3,7})\s+(?:pcs|pieces|units|stück|stk|kg)\.?\s+(?:per|a|pro|im|je)\s+(?:year|jahr)",
    re.I,
)
PPM_RE = re.compile(r"(\d{1,5})\s*ppm", re.I)
CHARGEBACK_RE = re.compile(
    r"(?:chargeback|rückbelastung|belastung)(?: of| von)?\s*(?:€|EUR)\s?(\d[\d.,]*)|(?:€|EUR)\s?(\d[\d.,]*)\s+"
    r"(?:chargeback|per complaint|je reklamation|pro reklamation)",
    re.I,
)
INCOTERM_RE = re.compile(r"\b(EXW|FCA|DAP)\b")
ISO_RE = re.compile(r"\b(20\d\d-\d\d-\d\d)\b")
DOTTED_RE = re.compile(r"\b(\d{1,2})\.(\d{1,2})\.(20\d\d)\b")
LONG_DATE_RE = re.compile(r"\b(\d{1,2})\.?\s+([A-Za-zäÄ]+)\s+(20\d\d)\b")
CLAUSE_RE = re.compile(r"preisgleitklausel|index(?:ation)? clause|indexklausel|index-?bindung", re.I)
NO_CLAUSE_RE = re.compile(
    r"\b(?:no|without|ohne|keine?)\s+(?:an?\s+)?(?:preisgleitklausel|index(?:ation)? clause|indexklausel)|"
    r"\bfixed price\b|\bfestpreis\b",
    re.I,
)
DEADBAND_RE = re.compile(r"(?:deadband|totband|schwelle)\s*(?:of|von)?\s*(\d+(?:[.,]\d+)?)\s*%|(\d+(?:[.,]\d+)?)\s*%\s*"
                         r"(?:deadband|totband)", re.I)  # fmt: skip
MONTH_NAMES = {
    name: i + 1
    for i, names in enumerate(
        [
            ("january", "januar", "jan"), ("february", "februar", "feb"), ("march", "märz", "maerz", "mar"),
            ("april", "apr"), ("may", "mai"), ("june", "juni", "jun"), ("july", "juli", "jul"),
            ("august", "aug"), ("september", "sep", "sept"), ("october", "oktober", "oct", "okt"),
            ("november", "nov"), ("december", "dezember", "dec", "dez"),
        ]
    )
    for name in names
}  # fmt: skip
PRICE = re.compile(r"(?:€|EUR)\s?(\d{1,6}(?:[.,]\d{3})*(?:[.,]\d{1,2})?)|(\d{1,6}(?:[.,]\d{3})*(?:[.,]\d{1,2})?)\s?(?:€|EUR\b|euros?\b)",
                   re.I)  # fmt: skip
NOT_THEIRS = re.compile(r"\byou (?:offered|proposed|suggest\w*)\b|\byour (?:offer|price|proposal) of\b|\bihr angebot\b",
                        re.I)  # fmt: skip
OFFER_WORDS = re.compile(
    r"\b(alternatively|alternativ|we (?:can|could|would|propose|offer)|our (?:price|offer|angebot)|beside this|"
    r"in return|price of|lower our price|wir (?:können|bieten)|unser (?:preis|angebot))\b",
    re.I,
)


def number(text):
    """'137.00', '137,00', '1.234,56', '1,234.56', '23.400' -> float."""
    text = str(text).strip().replace(" ", "").rstrip(".,")
    if re.fullmatch(r"\d{1,3}(?:[.,]\d{3})+", text):
        return float(re.sub(r"[.,]", "", text))
    if "," in text and "." in text:
        dec = "," if text.rfind(",") > text.rfind(".") else "."
        text = text.replace("." if dec == "," else ",", "").replace(dec, ".")
        return float(text)
    return float(text.replace(",", "."))


def parse_date(text):
    if m := ISO_RE.search(text):
        return m.group(1)
    if m := DOTTED_RE.search(text):
        d, mon, y = (int(x) for x in m.groups())
        if 1 <= d <= 31 and 1 <= mon <= 12:
            return f"{y}-{mon:02d}-{d:02d}"
    for d, mon, y in LONG_DATE_RE.findall(text):
        if (month := MONTH_NAMES.get(mon.lower())) and 1 <= int(d) <= 31:
            return f"{y}-{month:02d}-{int(d):02d}"
    return None


def pin_clause(case, text):
    """(ok, clause): the index-clause option a text names - None for "no clause" - or (False, None)
    when it names a clause that cannot be pinned to exactly one option."""
    if NO_CLAUSE_RE.search(text):
        return True, None
    opts = [o for o in (case.get("term_options") or {}).get("index_clause") or [] if o]
    named = [o for o in opts if re.search(rf"(?<![\w-]){re.escape(o['series'])}(?![\w-])", text, re.I)]
    if not named and len({o["series"] for o in opts}) == 1:
        named = opts  # the case has one series: "a Preisgleitklausel" means it
    if m := DEADBAND_RE.search(text):
        band = number(m.group(1) or m.group(2))
        named = [o for o in named if abs(o.get("deadband_pct", 0) - band) < 1e-6]
    if len({key(o) for o in named}) == 1:
        return True, named[0]
    return False, None


def terms_in(case, cond):
    """The negotiable terms one condition text names: {field: value}, or None if it names an index
    clause that cannot be pinned."""
    negotiable, t = case.get("negotiable", []), {}
    if "index_clause" in negotiable and (CLAUSE_RE.search(cond) or NO_CLAUSE_RE.search(cond)):
        ok, clause = pin_clause(case, cond)
        if not ok:
            return None
        t["index_clause"] = clause
    if "payment_days" in negotiable and (m := PAYMENT_RE.search(cond)):
        t["payment_days"] = int(m.group(1) or m.group(2))
    if "effective_date" in negotiable and (d := parse_date(cond)):
        t["effective_date"] = d
    if "lead_time_days" in negotiable and (m := LEAD_RE.search(cond)):
        t["lead_time_days"] = int(m.group(1))
    if "volume_per_year" in negotiable and (m := VOLUME_RE.search(cond)):
        t["volume_per_year"] = int(number(m.group(1)))
    if "contract_months" in negotiable and (m := MONTHS_RE.search(cond)):
        t["contract_months"] = int(m.group(1))
    if "ppm_commitment" in negotiable and (m := PPM_RE.search(cond)):
        t["ppm_commitment"] = int(m.group(1))
    if "chargeback_eur_per_complaint" in negotiable and (m := CHARGEBACK_RE.search(cond)):
        t["chargeback_eur_per_complaint"] = number(m.group(1) or m.group(2))
    if "incoterm" in negotiable and (m := INCOTERM_RE.search(cond)):
        t["incoterm"] = m.group(1)
    return t


def prose_alternatives(case, message):
    """The supplier's "Alternatively, with <terms>: EUR <price> per unit" lines as term dicts."""
    out = []
    body = re.sub(r"\s*\n\s*", " ", str(message.get("body") or message.get("text") or ""))
    for m in ALT_RE.finditer(body):
        t = terms_in(case, m.group("cond"))
        if t is None or not t:  # a price alone says nothing about which terms it is for
            continue
        try:
            t["unit_price"] = number(m.group("price"))
        except ValueError:
            continue
        out.append(t)
    return out


def sentences(text):
    return [s for s in re.split(r"(?<=[.!?])\s+", str(text or "").strip()) if s]


def prose_offers(case, body):
    """Every sentence that offers a price, with the terms it names (DualAgent's code reading)."""
    out = []
    for s in sentences(re.sub(r"\s*\n\s*", " ", body or "")):
        if NOT_THEIRS.search(s) or not OFFER_WORDS.search(s):
            continue
        prices = [m.group(1) or m.group(2) for m in PRICE.finditer(s)]
        if not prices:
            continue
        t = terms_in(case, s) or {}
        try:
            t["unit_price"] = number(prices[-1])  # "from EUR 126.53 to EUR 138.55": the new one
        except ValueError:
            continue
        out.append({"terms": t, "quote": s.strip()[:300], "source": "code"})
    return out

"""A background analyst per supplier thread (R11.1-R11.8), ported from DualAgent's `intel.py`.

On every supplier e-mail `Analyst.observe` updates a thread-safe `Intel` snapshot in two layers:
  code    at once, no model: the standing sheet and its move, status, signals, claim results,
          missing fields, who wrote, offers stated only in prose (`prose`), cost drivers the supplier
          names ("LCI-C rose 2.7 % ... 30 % of our cost"), questions, a rough tone
  model   one extraction call per e-mail in a worker thread: the same items read better, plus
          constraints, lever hints, relationship style, withdraw language. Every figure it returns
          must appear in the e-mail, or it is dropped (R11.2) - the model reads, it never sets a number.
Code does the arithmetic: the weighted effect of the named drivers against the increase asked for
(`cost_gap_pct`, R11.4), checked arguments for indices the supplier names, and `walk_risk` (R11.5) -
a signal for the tone and the prose lock-in, never a close rule.
"""

import copy
import json
import logging
import re
import threading
import time
from dataclasses import asdict, dataclass, field

from .. import claims as cl
from ..docs import standard_terms
from . import prose
from .terms import complete

log = logging.getLogger("arena")

GRACE_S = 12.0  # R11.3: the negotiator waits at most this long for the model layer
BOSS_ROLES = {"boss", "owner", "md", "ceo", "management", "director", "head", "gf", "board", "managing"}
WALK_WEIGHTS = {
    "final_offer": 0.45, "price_unchanged_2_rounds": 0.25, "price_unchanged_1_round": 0.10,
    "reply_delay_rising": 0.10, "validity_shrinking": 0.10, "escalated_to_boss": 0.15, "tone_drop": 0.20,
    "withdraw_language": 0.30,
}  # fmt: skip
STALE_TOL = 0.001
WITHDRAW = re.compile(
    r"\b(withdraw\w*|end (?:our|the|these) (?:talks|negotiation|discussion)s?|no further (?:concession|movement|room)s?|"
    r"cannot go (?:any )?(?:lower|further)|our last word|last offer|look elsewhere|terminate|break off|"
    r"not continue|step back from)\b",
    re.I,
)
POSITIVE = re.compile(r"\b(happy|pleased|glad|appreciate\w*|fair point|thank\w*|value|welcome|good cooperation)\b", re.I)
NEGATIVE = re.compile(
    r"\b(disappoint\w*|unacceptable|cannot accept|regret\w*|insult\w*|surpris\w*|frustrat\w*|not acceptable|"
    r"no reciprocal|final)\b",
    re.I,
)
RELATIONSHIP = re.compile(
    r"\b(generations?|family|long-standing|partnership|our foundry|regional partners|loyal\w*|years of)\b", re.I
)
DRIVER_VERB = re.compile(
    r"(?P<name>[\w-]+(?: [\w-]+){0,3}?)\s+(?:has |have )?(?P<verb>rose|risen|increased|went up|climbed|grew|"
    r"fell|dropped|decreased|went down|declined)\s+(?:by\s+)?(?P<chg>[+-]?\d+(?:[.,]\d+)?)\s?%",
    re.I,
)
SHARE = re.compile(
    r"(?P<share>\d+(?:[.,]\d+)?)\s?%\s+of\s+(?:our|the|its)\s+(?:total\s+|production\s+|unit\s+)?(?:cost|costs|price)",
    re.I,
)
# A supplier asking for faster payment, from its own words (R11.7, R12.19)
CASH_ASK = re.compile(
    r"faster payment|quick(?:er)? payment|early payment|shorter payment|cash ?flow|liquidit|"
    r"pay(?:ment)?\s+(?:of\s+)?(?:our\s+)?invoices\s+(?:with)?in\s+\d+\s+days|schnellere zahlung",
    re.I,
)

SYSTEM = """You are a procurement analyst reading one e-mail from an industrial supplier to our
purchasing team. Extract what it says - do not judge or advise. Copy every figure exactly as written.

Return ONE JSON object and nothing else:
{"prose_offers": [{"unit_price": 0.0, "payment_days": null, "effective_date": null, "other_terms": {},
                   "quote": "the sentence"}],
 "cost_drivers": [{"name": "LCI-C or 'energy'", "change_pct": 0.0, "cost_share_pct": null, "quote": "..."}],
 "named_indices": ["index series codes named, e.g. PPI-D351"],
 "constraints": ["limits they state, e.g. 'earliest effective date is 2027-01-01'"],
 "lever_hints": [{"field": "a negotiable field", "hint": "what they want or offer on it"}],
 "tone": 0,
 "relationship_style": "relationship | formal | transactional",
 "withdraw_language": false,
 "questions_to_us": ["questions they asked us"],
 "missing_info": ["what we still do not know that would help us"]}

- prose_offers: every price the supplier offers in the text with the terms it is tied to, including
  alternatives ("Alternatively, with 30 days net: EUR 137.00"). Not prices we offered, not old prices.
  effective_date as YYYY-MM-DD.
- tone: -2 (hostile) .. +2 (warm). withdraw_language: true only if they threaten to end the talks."""


@dataclass
class Mail:
    status: str | None = None
    c: float | None = None
    price: float | None = None
    delay: float | None = None
    validity: float | None = None
    role: str | None = None
    tone: float | None = None
    withdraw: bool = False


@dataclass
class Intel:
    supplier_id: str
    mails: int = 0
    status: str | None = None
    sender: str | None = None
    standing: dict = field(default_factory=dict)
    signals: dict = field(default_factory=dict)
    claim_results: list = field(default_factory=list)
    missing_fields: list = field(default_factory=list)
    unchanged_rounds: int = 0
    prose_offers: list = field(default_factory=list)  # {terms, stated, quote, source, in_sheet}
    alternatives: list = field(default_factory=list)  # R13.6 lines of the latest mail
    cost_drivers: list = field(default_factory=list)
    cost_impact_pct: float | None = None
    asked_pct: float | None = None
    cost_gap_pct: float | None = None
    new_claims: list = field(default_factory=list)
    constraints: list = field(default_factory=list)
    lever_hints: list = field(default_factory=list)
    cash_ask: bool = False
    tone: float | None = None
    relationship_style: str | None = None
    withdraw_language: bool = False
    questions: list = field(default_factory=list)
    walk_risk: float = 0.0
    walk_signals: dict = field(default_factory=dict)
    llm: str = "off"

    def to_log(self):
        d = asdict(self)
        d["new_claims"] = [{"key": c.key, "sentence": c.sentence, "favourable": c.favourable} for c in self.new_claims]
        return d


def weighted_impact(drivers):
    """The price effect of the drivers the supplier named, in %: sum of change x cost share (R11.4)."""
    parts = [d["change_pct"] * d["share_pct"] / 100 for d in drivers if d.get("share_pct") is not None]
    return round(sum(parts), 2) if parts else None


def unchanged(mails):
    """How many replies in a row left the standing offer where it was."""
    n = 0
    for a, b in zip(reversed(mails[:-1]), reversed(mails[1:]), strict=True):
        x, y = (a.c, b.c) if a.c and b.c else (a.price, b.price)
        if x is None or y is None or abs(x - y) > STALE_TOL * x:
            break
        n += 1
    return n


def _boss(role):
    return bool(role) and any(w in role.lower() for w in BOSS_ROLES)


def walk_risk(mails):
    """(0..1, {signal: points}) over the whole thread, oldest mail first (R11.5)."""
    if not mails:
        return 0.0, {}
    last, prev = mails[-1], mails[:-1]
    if last.status == "walked_away":
        return 1.0, {"walked_away": 1.0}
    sig = {}
    if last.status == "final_offer":
        sig["final_offer"] = WALK_WEIGHTS["final_offer"]
    if (n := unchanged(mails)) >= 2:
        sig["price_unchanged_2_rounds"] = WALK_WEIGHTS["price_unchanged_2_rounds"]
    elif n == 1:
        sig["price_unchanged_1_round"] = WALK_WEIGHTS["price_unchanged_1_round"]
    delays = [m.delay for m in prev if m.delay is not None]
    if last.delay is not None and delays and last.delay > min(delays):
        sig["reply_delay_rising"] = WALK_WEIGHTS["reply_delay_rising"]
    valid = [m.validity for m in prev if m.validity is not None]
    if last.validity is not None and valid and last.validity < max(valid):
        sig["validity_shrinking"] = WALK_WEIGHTS["validity_shrinking"]
    if _boss(last.role) and any(m.role and not _boss(m.role) for m in prev):
        sig["escalated_to_boss"] = WALK_WEIGHTS["escalated_to_boss"]
    tones = [m.tone for m in prev if m.tone is not None]
    if last.tone is not None and tones and tones[-1] - last.tone >= 2:
        sig["tone_drop"] = WALK_WEIGHTS["tone_drop"]
    if last.withdraw:
        sig["withdraw_language"] = WALK_WEIGHTS["withdraw_language"]
    return round(min(1.0, sum(sig.values())), 2), sig


def tone_by_code(body):
    pos, neg = len(POSITIVE.findall(body or "")), len(NEGATIVE.findall(body or ""))
    return max(-2.0, min(2.0, round((pos - 2 * neg) / 2)))


def appears(value, text):
    """R11.2: a figure the model returned is real only if the e-mail has it."""
    if value is None:
        return False
    try:
        v = float(value)
    except (TypeError, ValueError):
        return False
    forms = {f"{v:.2f}", f"{v:.1f}", f"{v:g}", f"{v:.2f}".replace(".", ","), f"{v:.1f}".replace(".", ",")}
    if v == int(v):
        forms.add(str(int(v)))
    return any(re.search(rf"(?<![\d.,]){re.escape(f)}(?![\d])", text or "") for f in forms)


def drivers_by_code(body, series_ids=()):
    out = []
    for s in prose.sentences(re.sub(r"\s*\n\s*", " ", body or "")):
        verb, share = DRIVER_VERB.search(s), SHARE.search(s)
        if not verb:
            continue
        chg = prose.number(verb.group("chg").lstrip("+"))
        if verb.group("verb").lower() in ("fell", "dropped", "decreased", "went down", "declined"):
            chg = -abs(chg)
        name = verb.group("name").split()[-1]
        series = next((i for i in series_ids if i.lower() == name.lower()), None)
        out.append({"name": name, "series": series, "change_pct": chg,
                    "share_pct": prose.number(share.group("share")) if share else None,
                    "quote": s.strip(), "source": "code"})  # fmt: skip
    return out


def clean_extraction(parsed, body, negotiable):
    """R11.2: keep only what the e-mail itself says - every figure must appear in it."""
    if not isinstance(parsed, dict):
        return {}
    out = dict(parsed)
    offers = []
    for o in parsed.get("prose_offers") or []:
        if not isinstance(o, dict) or not appears(o.get("unit_price"), body):
            continue
        t = {"unit_price": float(o["unit_price"])}
        if o.get("payment_days") is not None and "payment_days" in negotiable and appears(o["payment_days"], body):
            t["payment_days"] = int(float(o["payment_days"]))
        if o.get("effective_date") and "effective_date" in negotiable:
            t["effective_date"] = str(o["effective_date"])[:10]
        for f, v in (o.get("other_terms") or {}).items():
            if f in negotiable and v is not None and (not isinstance(v, int | float) or appears(v, body)):
                t[f] = v
        offers.append({"terms": t, "quote": str(o.get("quote") or "")[:300], "source": "model"})
    out["prose_offers"] = offers
    drivers = []
    for d in parsed.get("cost_drivers") or []:
        if not isinstance(d, dict) or not appears(d.get("change_pct"), body):
            continue
        share = d.get("cost_share_pct")
        drivers.append({
            "name": str(d.get("name") or "?"), "change_pct": float(d["change_pct"]),
            "share_pct": float(share) if share is not None and appears(share, body) else None,
            "quote": str(d.get("quote") or "")[:300], "source": "model",
        })  # fmt: skip
    out["cost_drivers"] = drivers
    return out


class Analyst:
    """One supplier thread. `observe` with every new state of the thread; `snapshot` is safe from any
    thread at any time."""

    def __init__(self, case, sid, package=None, complete_fn=None, pool=None, cost_fn=None):
        self.case, self.sid, self.package = case, sid, package
        self.complete, self.pool = complete_fn, pool
        self.cost_fn = cost_fn  # (terms, std) -> C, for the unchanged-offer test
        self._lock = threading.Lock()
        self._intel = Intel(supplier_id=sid, llm="off" if complete_fn is None else "pending")
        self._llm, self._pending, self._events = {}, {}, []
        self.series_ids = self._series_ids()

    def _series_ids(self):
        ids = set()
        if self.package is not None:
            try:
                ids |= {r["id"] for r in self.package.query("SELECT id FROM index_series")}
            except Exception:
                pass
        ids |= {k[4:].split("@")[0] for k in (self.case.get("facts") or {}) if k.startswith("idx:")}
        return sorted(ids, key=len, reverse=True)

    def observe(self, events):
        with self._lock:
            self._events = list(events)
        self._rebuild()
        mails = [i for i, m in enumerate(events) if m.get("from") != "buyer"]
        if self.complete is not None and self.pool is not None and mails:
            i = mails[-1]
            with self._lock:
                if i not in self._llm and i not in self._pending:
                    self._pending[i] = self.pool.submit(self._extract, i, events[i])
        return self

    def wait(self, timeout=GRACE_S):
        """Wait up to `timeout` seconds for the model layer of the latest mail (R11.3)."""
        with self._lock:
            futures = list(self._pending.values())
        deadline = time.monotonic() + max(0.0, timeout)
        for f in futures:
            try:
                f.result(timeout=max(0.0, deadline - time.monotonic()))
            except Exception:
                return False
        return True

    def snapshot(self):
        with self._lock:
            return copy.deepcopy(self._intel)

    def _c(self, terms, std):
        if not self.cost_fn or not terms.get("unit_price"):
            return None
        try:
            return self.cost_fn(terms, std)
        except Exception:
            return None

    def _rebuild(self):
        with self._lock:
            events, llm = list(self._events), dict(self._llm)
        case, negotiable = self.case, self.case.get("negotiable", [])
        std = standard_terms(events)
        sup = [(i, m) for i, m in enumerate(events) if m.get("from") != "buyer"]
        if not sup:
            return
        intel = Intel(supplier_id=self.sid, mails=len(sup))
        history = []
        for i, m in sup:
            sheets = m.get("term_sheets") or []
            terms = sheets[0]["terms"] if sheets else {}
            x = llm.get(i) or {}
            sig = m.get("signals") or {}
            history.append(Mail(
                status=m.get("status"), c=self._c(terms, std), price=terms.get("unit_price"),
                delay=sig.get("reply_delay_days"), validity=sig.get("validity_days"),
                role=(m.get("from") or "").split("@")[0] or None,
                tone=x.get("tone") if isinstance(x.get("tone"), int | float) else tone_by_code(m.get("body")),
                withdraw=bool(x.get("withdraw_language")) or bool(WITHDRAW.search(m.get("body") or "")),
            ))  # fmt: skip
        i, last = sup[-1]
        x = llm.get(i) or {}
        sheets = last.get("term_sheets") or []
        body = last.get("body") or ""
        intel.status, intel.sender = last.get("status"), last.get("from")
        intel.signals = dict(last.get("signals") or {})
        intel.claim_results = list(last.get("claim_results") or [])
        intel.missing_fields = list(last.get("missing_fields") or [])
        intel.standing = {"id": sheets[0]["term_sheet_id"], "terms": sheets[0]["terms"]} if sheets else {}
        intel.unchanged_rounds = unchanged(history)
        intel.walk_risk, intel.walk_signals = walk_risk(history)
        intel.tone, intel.withdraw_language = history[-1].tone, history[-1].withdraw
        intel.cash_ask = bool(CASH_ASK.search(body))

        # offers stated only in prose (R11.8) and the "Alternatively" lines (R13.6)
        intel.alternatives = prose.prose_alternatives(case, last)
        found = [*({"terms": t, "quote": "", "source": "alternative"} for t in intel.alternatives),
                 *prose.prose_offers(case, body), *(x.get("prose_offers") or [])]  # fmt: skip
        base, seen = intel.standing.get("terms") or {}, []
        for o in found:
            stated = o["terms"]
            sheet = next((s for s in sheets if all(s["terms"].get(k) == v for k, v in stated.items())), None)
            terms = complete(case, {**(sheet["terms"] if sheet else {**base, **stated})}, std)
            if terms.get("unit_price") is None or any(terms == s for s in seen):
                continue
            seen.append(terms)
            intel.prose_offers.append({"terms": terms, "stated": stated, "quote": o.get("quote", ""),
                                       "source": o.get("source"), "in_sheet": sheet["term_sheet_id"] if sheet else None})

        # cost drivers -> the weighted effect against the increase asked for (R11.4)
        drivers = {}
        for i2, m in sup:
            for d in drivers_by_code(m.get("body"), self.series_ids):
                drivers.setdefault((d["series"] or d["name"]).lower(), d)
            for d in (llm.get(i2) or {}).get("cost_drivers") or []:
                series = next((s for s in self.series_ids if s.lower() == d["name"].lower()), None)
                k = (series or d["name"]).lower()
                if k not in drivers or (drivers[k]["share_pct"] is None and d["share_pct"] is not None):
                    drivers[k] = {**d, "series": series}
        intel.cost_drivers = list(drivers.values())
        intel.cost_impact_pct = weighted_impact(intel.cost_drivers)
        intel.asked_pct = self._asked_pct(events)
        if intel.cost_impact_pct is not None and intel.asked_pct is not None:
            intel.cost_gap_pct = round(intel.asked_pct - intel.cost_impact_pct, 2)

        # indices the supplier named that the data covers -> checked arguments. A rising index argues
        # its side and is kept out unless it rose less than half the increase asked for (R13.9).
        named = {d["series"] for d in intel.cost_drivers if d.get("series")}
        for _, m in sup:
            text = m.get("body") or ""
            named |= {s for s in self.series_ids if re.search(rf"(?<![\w-]){re.escape(s)}(?![\w-])", text)}
        for i2, _ in sup:
            named |= {s for s in (llm.get(i2) or {}).get("named_indices") or [] if s in self.series_ids}
        for series in sorted(named):
            got = cl.index_change(self.package, case, series) if self.package else None
            if not got:
                continue
            chg, a, b = got
            asked = intel.asked_pct
            intel.new_claims.append(cl.Claim(
                key=f"index:{series}", kind="index", ids=[a, b], figure=chg,
                favourable=chg <= 0 or (asked is not None and chg < asked / 2),
                sentence=f"{cl.series_name(self.package, series)} changed {chg:+.1f}% "
                f"from {a.split('@')[1]} to {b.split('@')[1]} ({a}, {b}).",
                note="an index the supplier named", strength=max(0.0, (asked or 0) - chg) / 4,
            ))  # fmt: skip

        intel.constraints = [str(s)[:200] for s in x.get("constraints") or []][:6]
        intel.lever_hints = [
            {"field": h.get("field"), "hint": str(h.get("hint") or "")[:200]}
            for h in x.get("lever_hints") or []
            if isinstance(h, dict) and h.get("field") in negotiable
        ][:6]
        style = x.get("relationship_style")
        intel.relationship_style = (
            style if style in ("relationship", "formal", "transactional")
            else "relationship" if RELATIONSHIP.search(" ".join(m.get("body") or "" for _, m in sup)) else None
        )  # fmt: skip
        intel.questions = [str(q)[:300] for q in x.get("questions_to_us") or []] or [
            s for s in prose.sentences(re.sub(r"\s*\n\s*", " ", body)) if s.endswith("?")
        ][:4]
        if self.complete is None:
            intel.llm = "off"
        else:
            intel.llm = "failed" if llm.get(i) == {} else "done" if i in llm else "pending"
        with self._lock:
            self._intel = intel

    def _asked_pct(self, events):
        trigger = cl._fact(self.package, self.case, self.case["trigger_doc"]) if self.case.get("trigger_doc") else None
        if trigger and trigger.get("asked_pct") is not None:
            return float(trigger["asked_pct"])
        current = self.case["buyer"].get("current_unit_price")
        prices = (s["terms"].get("unit_price") for m in events if m.get("from") != "buyer"
                  for s in m.get("term_sheets") or [])  # fmt: skip
        opening = next(prices, None)
        if current and opening and self.case.get("type") in ("price_increase", "raw_material") and opening > current:
            return round((opening / current - 1) * 100, 2)
        return None

    def _extract(self, index, mail):
        user = "\n\n".join([
            f"NEGOTIABLE FIELDS: {json.dumps(self.case['negotiable'])}; options "
            f"{json.dumps(self.case.get('term_options') or {}, default=str)}",
            f"THEIR TERM SHEETS IN THIS E-MAIL: {json.dumps(mail.get('term_sheets') or [], default=str)}",
            f"E-MAIL from {mail.get('from')} (status {mail.get('status')}):\n{(mail.get('body') or '')[:6000]}",
        ])  # fmt: skip
        parsed = {}
        try:
            from .llm import parse_json

            parsed = clean_extraction(parse_json(self.complete(SYSTEM, user)), mail.get("body") or "",
                                      self.case.get("negotiable", []))  # fmt: skip
        except Exception as e:
            log.info("%s analyst extraction failed: %s", self.sid, e)
            parsed = {}
        with self._lock:
            self._llm[index] = parsed
            self._pending.pop(index, None)
        self._rebuild()
        return parsed

"""Model calls with hard timeouts: a hung call never holds the case (R10.2).

`from_env(timeout)` gives `complete(system, user, timeout=None) -> str` on LLM_PROVIDER (as the kit's
`llm_from_env`); each call runs in a worker thread and is abandoned at its deadline. `SPEC_LLM=0` (or
no credentials) switches the model off - the agent then writes every e-mail by code.
"""

import json
import logging
import os
import re
from concurrent.futures import ThreadPoolExecutor
from concurrent.futures import TimeoutError as FuturesTimeout

import httpx

log = logging.getLogger("arena")
POOL = ThreadPoolExecutor(max_workers=32, thread_name_prefix="spec-llm")


def parse_json(text):
    """The first JSON object in a model reply (tolerates code fences and chatter)."""
    match = re.search(r"\{.*\}", text or "", re.S)
    if not match:
        raise ValueError(f"no JSON in reply: {str(text)[:200]}")
    return json.loads(match.group(0))


def with_deadline(fn, timeout, *args):
    """fn(*args) in a worker thread; TimeoutError after `timeout` seconds (the call is abandoned)."""
    future = POOL.submit(fn, *args)
    try:
        return future.result(timeout=max(0.1, timeout))
    except FuturesTimeout:
        future.cancel()
        raise TimeoutError(f"model call over {timeout:.0f}s") from None


def from_env(default_timeout=35.0):
    """A `complete(system, user, timeout=None)` on the configured provider, or None (no model)."""
    if os.environ.get("SPEC_LLM", "1").lower() in ("0", "false", "no", "off"):
        return None
    provider, model = os.environ.get("LLM_PROVIDER", "openai"), os.environ.get("LLM_MODEL")
    if not model:
        log.warning("spec agent: no LLM_MODEL - code-written e-mails")
        return None
    if provider == "anthropic":
        if not (os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("ANTHROPIC_AUTH_TOKEN")):
            log.warning("spec agent: no Anthropic credentials - code-written e-mails")
            return None
        import anthropic

        client = anthropic.Anthropic(max_retries=0)
        extra = {"output_config": {"effort": e}} if (e := os.environ.get("LLM_EFFORT")) else {}

        def call(system, user, timeout):
            r = client.messages.create(
                model=model, max_tokens=4000, system=system, timeout=timeout,
                messages=[{"role": "user", "content": user}], **extra,
            )  # fmt: skip
            return "".join(b.text for b in r.content if b.type == "text")

    else:
        key = os.environ.get("LLM_API_KEY")
        if not key:
            log.warning("spec agent: no LLM_API_KEY - code-written e-mails")
            return None
        base = os.environ.get("LLM_BASE_URL", "https://api.openai.com/v1").rstrip("/")
        http = httpx.Client(headers={"Authorization": f"Bearer {key}"})

        def call(system, user, timeout):
            body = {
                "model": model,
                "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
                "response_format": {"type": "json_object"},
            }
            r = http.post(f"{base}/chat/completions", json=body, timeout=timeout)
            r.raise_for_status()
            return r.json()["choices"][0]["message"]["content"]

    def complete(system, user, timeout=None):
        t = timeout or default_timeout
        return with_deadline(call, t + 1.0, system, user, t)

    return complete

"""Term sheets around a target C (sections 3 and 6, R11.9-R11.11, R12.2, R12.7-R12.10).

`Ctx` is one thread as the sheets see it: the case, the supplier's standard terms, our estimate of
it, and the supplier's best sheet on the table. Every price comes from `pricing.price_for`, so every
sheet costs exactly the target (R13.8); every sheet passes `guard` (R11.11) and `no_regress` (R12.10)
before it goes out.

  structure    the supplier's terms, broken must-haves repaired (R11.9), coverage locked (R12.2),
               moved where both sides gain (R3.2); its asks beyond our reference put back where that
               saves us money (R3.3)
  price round  up to three sheets at the target: our terms, their terms, a give (R6.1) with a shared
               surplus (R6.2); lean / recommended / other with a decoy (R6.4); two sheets when the
               supplier asked for something (R6.3); its own terms just under its price when nothing
               fits (R6.6)
  floors       no sheet under max(full cost x 0.97, 75 % of its price) (R6.5); faster payment may go
               lower, priced at the supplier's cost of money (R12.9)
"""

import math
from dataclasses import dataclass

from ..cost import OPS, closing_terms, must_haves_ok, supplier_value
from . import estimate as est_mod
from . import pricing
from .terms import COVERAGE, complete, distance, key, options, order, same, step

SURPLUS_SHARE = 0.5  # R6.2: our share of the gain from a give
DECOY_GAP = 0.02  # R6.4: the lean sheet is the recommended one 2 % cheaper, one term worse for them
FLOOR_COST_K = 0.97  # R6.5: never under the estimated full cost x 0.97
FLOOR_PRICE_K = 0.75  # R6.5: never more than 25 % under the supplier's price
OUT_OF_REACH_K = 0.99  # R6.6: its own terms at 99 % of its price
REGRESS_TOL = 0.001  # R12.10: within 0.1 % of an offer the supplier made is no offer
VOLATILE_PCT = 15.0  # R13.11
REFERENCE_FIELDS = ("payment_days", "volume_per_year", "contract_months", "lead_time_days", "index_clause")


@dataclass
class Ctx:
    case: dict
    std: dict
    est: est_mod.Estimate
    their: dict  # the supplier's best sheet on the table (R3.1), completed
    playbook: dict
    volatile: object = None  # series -> bool (R13.11)

    def c(self, terms):
        return est_mod.cost(self.case, terms, self.std, self.est)

    @property
    def supplier(self):
        return self.est.supplier(self.case, self.std) if self.est else None

    @property
    def their_price(self):
        return self.their.get("unit_price") or 0.0

    @property
    def c_theirs(self):
        return self.c(self.their)

    def ok(self, terms):
        return must_haves_ok(self.case, terms, self.std)

    def allowed(self, field, terms=None):
        """The options of a term we may offer: valid for the must-haves; index clauses as the playbook
        allows (any / deadband >= 3 % / avoid) and never on a volatile series (R13.11)."""
        opts = options(self.case, field, self.std)
        if terms is not None:
            opts = [o for o in opts if self.ok({**terms, field: o})] or opts
        if field != "index_clause":
            return opts
        stance = (self.playbook or {}).get("index", "any")
        keep = [o for o in opts if o is None or not (self.volatile and self.volatile(o["series"]))]
        if stance == "avoid":
            keep = [o for o in keep if o is None] or keep
        elif stance == "deadband":
            keep = [o for o in keep if o is None or o.get("deadband_pct", 0) >= 3] or keep
        return keep or opts


# --- structure -----------------------------------------------------------------------------------
def repair(case, terms, std=None):
    """R11.9: each broken must-have moved to the nearest allowed value that keeps it."""
    out, std = dict(terms), std or {}
    for m in (case.get("buyer") or {}).get("must_haves") or []:
        if must_haves_ok(case, out, std) or m["field"] not in case.get("negotiable", []):
            continue
        current = {**std, **out}.get(m["field"])
        allowed = [o for o in (case.get("term_options") or {}).get(m["field"]) or [m["value"]]
                   if o is not None and OPS[m["op"]](o, m["value"])]  # fmt: skip
        if allowed:
            near = isinstance(current, int | float) and all(isinstance(o, int | float) for o in allowed)
            out[m["field"]] = min(allowed, key=lambda o: abs(o - current)) if near else allowed[0]
    return out


def cover(ctx, combo, price):
    """R12.2: the coverage terms (contract months x volume) at the joint option that costs us least at
    `price` - committing the full need for the full horizon whenever that lowers C. Ties (within EUR 1)
    go to the values closest to the supplier's own. Trusts the table when coverage does not pay
    (P08: a fallback price below the offer)."""
    fields = [f for f in COVERAGE if f in ctx.case["negotiable"] and (ctx.case.get("term_options") or {}).get(f)]
    if not fields:
        return dict(combo)
    grids = [[(f, o) for o in ctx.allowed(f, combo)] for f in fields]
    best, best_c = dict(combo), ctx.c({**combo, "unit_price": price})
    import itertools

    for pick in itertools.product(*grids):
        t = {**combo, **dict(pick)}
        if not ctx.ok(t):
            continue
        c = ctx.c({**t, "unit_price": price})
        closer = sum(distance(t[f], combo.get(f)) for f in fields) < sum(distance(best[f], combo.get(f)) for f in fields)
        if c < best_c - 1 or (abs(c - best_c) <= 1 and closer):
            best, best_c = t, c
    return best


def base_combo(ctx, terms):
    """Their non-price terms, completed from the standard terms and snapped to the case's options."""
    full = complete(ctx.case, {k: v for k, v in terms.items()}, ctx.std)
    full.pop("unit_price", None)
    return full


def mutual_combo(ctx, terms, price=None):
    """R3.2: their non-price terms moved toward what the supplier prefers for as long as that also
    lowers our C (e.g. a longer contract that covers our whole need)."""
    out = base_combo(ctx, terms)
    price = price if price is not None else terms.get("unit_price") or ctx.their_price

    def c(combo):
        return ctx.c({**combo, "unit_price": price})

    for f in [f for f in out if f in ctx.case["negotiable"]]:
        v = step(ctx.case, f, out[f], ctx.std, toward_supplier=True)
        while v is not None and ctx.ok({**out, f: v}) and c({**out, f: v}) < c(out) - 1e-6:
            out[f] = v
            v = step(ctx.case, f, v, ctx.std, toward_supplier=True)
    return out


def reference_combo(ctx, combo, price):
    """R3.3: terms the supplier pulled beyond our reference (the buyer's plan) put back where that
    saves us money - what it asks for is paid for in price."""
    plan = complete(ctx.case, {"index_clause": None}, {})
    out = dict(combo)
    for f in REFERENCE_FIELDS:
        if f not in ctx.case["negotiable"] or f not in out or key(plan.get(f)) == key(out[f]):
            continue
        if f != "index_clause" and plan.get(f) is None:
            continue
        moved = {**out, f: plan.get(f)}
        if ctx.ok(moved) and ctx.c({**moved, "unit_price": price}) < ctx.c({**out, "unit_price": price}):
            out = moved
    return out


def structure(ctx, price):
    """The structure we negotiate the price on: their terms repaired, coverage locked at `price`,
    moved where both sides gain."""
    base = base_combo(ctx, repair(ctx.case, ctx.their, ctx.std))
    base = cover(ctx, base, price)
    return mutual_combo(ctx, {**base, "unit_price": price}, price)


# --- prices --------------------------------------------------------------------------------------
def floor(ctx):
    """R6.5: max(estimated full cost x 0.97, 75 % of the supplier's price)."""
    cut = FLOOR_PRICE_K * ctx.their_price
    if ctx.est and ctx.est.full_cost and ctx.est.source != "opening":
        return max(ctx.est.full_cost * FLOOR_COST_K, cut)
    return cut


def indifference_price(ctx, give, reference, ref_price):
    """The price for `give` that leaves the supplier exactly as well off in cash as `reference` at
    `ref_price` (`supplier_value` at its estimated cost of money). None if it cannot be computed."""
    sup = ctx.est.as_supplier(ctx.case, ctx.std) if ctx.est else None
    if sup is None:
        return None
    try:
        v_ref = supplier_value(ctx.case, {**reference, "unit_price": ref_price}, sup)
        v0 = supplier_value(ctx.case, {**give, "unit_price": 0.0}, sup)
        v1 = supplier_value(ctx.case, {**give, "unit_price": 1.0}, sup)
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        return None
    if v1 - v0 <= 0:
        return None
    return (v_ref - v0) / (v1 - v0)


def give_price(p_equal, p_indifferent):
    """R6.2: a give priced halfway between our equal-cost price and the supplier's indifference
    price, when the term is worth more to it than it costs us; else equal cost."""
    if p_equal is None:
        return None
    if p_indifferent is None or p_indifferent >= p_equal:
        return p_equal
    return math.floor((p_equal - SURPLUS_SHARE * (p_equal - p_indifferent)) * 100) / 100


def structure_floor(ctx, combo, base, floor_price):
    """R12.9: a floor per structure - the price that pays the supplier as much as `base` at the floor
    (faster payment is worth more to it, so that sheet may go lower), never under 75 % of its price."""
    p = indifference_price(ctx, combo, base, floor_price)
    if p is None:
        return floor_price
    return max(FLOOR_PRICE_K * ctx.their_price, min(floor_price, p))


def priced(ctx, combo, target, lo):
    """`combo` at the whole-cent price that costs `target`, if that price is credible: at or above `lo`
    and under the supplier's price. Else None."""
    p = pricing.price_for(ctx.case, combo, ctx.std, target, ctx.supplier, ctx.their_price)
    if p is None or p < lo - 0.005 or p >= ctx.their_price:
        return None
    return complete(ctx.case, {**combo, "unit_price": p}, ctx.std)


# --- price-round sheets (R6) -----------------------------------------------------------------------
def our_terms(ctx, base, open_fields):
    """Every open term at the option that costs us least (R6.1 "our terms")."""
    price = ctx.their_price
    ours = dict(base)
    for f in open_fields:
        opts = ctx.allowed(f, ours)
        if opts:
            ours[f] = min(opts, key=lambda v, f=f: (ctx.c({**ours, f: v, "unit_price": price}), key(v) != key(ours[f])))
    return ours


def price_sheets(ctx, base, target, levers, floor_price, open_fields=(), asks=None):
    """Up to three sheets at `target` (R6.1): our terms first, their terms, a give - arranged lean /
    recommended / other with the decoy (R6.4). When the supplier asked for terms, `ask_sheets`."""
    if asks and (out := ask_sheets(ctx, base, target, asks, floor_price)):
        return out
    candidates = []
    ours = our_terms(ctx, base, open_fields)
    if ours != base:
        candidates.append(("our terms", ours))
    candidates.append(("their terms", base))
    for f in levers:
        if f in base and f not in COVERAGE and (v := step(ctx.case, f, base[f], ctx.std, toward_supplier=True)) is not None:
            if ctx.ok({**base, f: v}) and (f != "index_clause" or v in ctx.allowed(f)):
                candidates.append((f"{f} toward them", {**base, f: v}))
                break
    out, cap = [], None
    for label, combo in candidates:
        lo = structure_floor(ctx, combo, base, floor_price)
        sheet = priced(ctx, combo, target, lo)
        if label == "their terms" and sheet:
            cap = sheet["unit_price"]
        if sheet and cap and label.endswith("toward them"):
            p = give_price(sheet["unit_price"], indifference_price(ctx, combo, base, cap))
            sheet = complete(ctx.case, {**combo, "unit_price": max(p, lo)}, ctx.std) if p else None
        if sheet and ctx.ok(sheet) and not any(same(sheet, s) for _, s in out):
            out.append((label, sheet))
    return with_decoy(ctx, out, levers, floor_price)


def ask_sheets(ctx, base, target, asks, floor_price):
    """R6.3: the supplier asked for something - exactly its ask at a lower price (shared surplus), and
    our reference terms at the target. No third sheet that blurs the trade. [] if it does not work."""
    price = ctx.their_price
    ref = reference_combo(ctx, base, price)
    give = {**ref, **asks}
    if not ctx.ok(give) or same(complete(ctx.case, give, ctx.std), complete(ctx.case, ref, ctx.std)):
        return []
    ref_sheet = priced(ctx, ref, target, floor_price)
    if ref_sheet is None:
        return []
    lo = structure_floor(ctx, give, ref, floor_price)
    p_equal = pricing.price_for(ctx.case, give, ctx.std, target, ctx.supplier, price)
    p = give_price(p_equal, indifference_price(ctx, give, ref, ref_sheet["unit_price"]))
    if p is None:
        return []
    ask_sheet = complete(ctx.case, {**give, "unit_price": max(p, lo)}, ctx.std)
    if ask_sheet["unit_price"] >= price:
        return []
    return [("their ask", ask_sheet), ("reference", ref_sheet)]


def with_decoy(ctx, out, levers, floor_price):
    """R6.4: [lean, recommended, other]. The lean sheet is the recommended one DECOY_GAP cheaper with
    the term the supplier values most moved our way - safe: if it takes the lean one, we gain."""
    if not out:
        return out
    middle = next((t for label, t in out if label == "their terms"), out[0][1])
    lean = dict(middle)
    fields = [f for f in [*levers, *ctx.case["negotiable"]] if f in lean and f != "unit_price" and f not in COVERAGE]
    moved = False
    for f in dict.fromkeys(fields):
        v = step(ctx.case, f, lean[f], ctx.std, toward_supplier=False)
        if v is not None and ctx.ok({**lean, f: v}) and (f != "index_clause" or v in ctx.allowed(f)):
            lean[f], moved = v, True
            break
    if not moved:
        return out
    lean = complete(ctx.case, {**lean, "unit_price": round(middle["unit_price"] * (1 - DECOY_GAP), 2)}, ctx.std)
    if lean["unit_price"] < floor_price or any(same(lean, t) for _, t in out) or not ctx.ok(lean):
        return out
    rest = [(label, t) for label, t in out if t is not middle][:1]
    return [("lean", lean), ("recommended", middle), *rest]


def out_of_reach(ctx, base, floor_price):
    """R6.6: no sheet fits the target - its own terms at max(floor, 99 % of its price), if they keep
    the must-haves."""
    p = max(floor_price, OUT_OF_REACH_K * ctx.their_price)
    t = complete(ctx.case, {**base, "unit_price": round(p, 2)}, ctx.std)
    return [("their terms", t)] if ctx.ok(t) and t["unit_price"] < ctx.their_price else []


# --- variants of the first menu ---------------------------------------------------------------------
def payment_probe(ctx, sheet, target, floor_price, slopes=None):
    """R12.7: the sheet with payment days at the supplier's own value, or at 30 days, at equal C - its
    pick reveals its cost of money. None if it does not fit."""
    if "payment_days" not in ctx.case["negotiable"]:
        return None
    pay = ctx.allowed("payment_days", sheet)
    own = complete(ctx.case, ctx.their, ctx.std).get("payment_days")
    want = 30 if ("payment_days" in (slopes or {}) or own == sheet.get("payment_days")) else own
    other = min(pay, key=lambda d: abs(d - (want or 30))) if pay else None
    if other is None or other == sheet.get("payment_days"):
        return None
    combo = {**{k: v for k, v in sheet.items() if k != "unit_price"}, "payment_days": other}
    lo = structure_floor(ctx, combo, {k: v for k, v in sheet.items() if k != "unit_price"}, floor_price)
    return priced(ctx, combo, target, lo)


def index_variant(ctx, sheet, target, floor_price):
    """R12.8: the supplier insists on an index clause - offer its own series with the deadband that
    costs us least (never a 0 % deadband we can avoid), within the playbook and never volatile."""
    theirs = ctx.their.get("index_clause")
    if "index_clause" not in ctx.case["negotiable"] or not theirs or sheet.get("index_clause"):
        return None
    same_series = [o for o in ctx.allowed("index_clause") if o and o.get("series") == theirs.get("series")]
    if not same_series:
        return None
    combo = {k: v for k, v in sheet.items() if k != "unit_price"}
    best = min(same_series, key=lambda o: (ctx.c({**combo, "index_clause": o, "unit_price": ctx.their_price}),
                                          -o.get("deadband_pct", 0)))  # fmt: skip
    return priced(ctx, {**combo, "index_clause": best}, target, floor_price)


# --- guards ----------------------------------------------------------------------------------------
def lock_coverage(ctx, sheets, cover_values):
    """R12.2: once sheet A covers the need, no sheet covers less."""
    out = []
    for label, t in sheets:
        t = dict(t)
        for f, v in (cover_values or {}).items():
            if isinstance(v, int | float) and (t.get(f) or 0) < v:
                t[f] = v
        out.append((label, t))
    return out


def guard(ctx, sheets, target, supplier_sheets, last_sheets=None):
    """R11.11 / R6.7, code's last word on every sheet: it costs us at most the target (within the
    whole-cent tolerance), is cheaper for us than the supplier's standing offer, is not one of the
    supplier's own sheets and keeps the must-haves. If nothing survives: our last sheets."""
    own = [complete(ctx.case, t, ctx.std) for t in supplier_sheets]
    c_theirs, out = ctx.c_theirs, []
    for label, t in sheets:
        if t is None or t.get("unit_price") is None:
            continue
        c = ctx.c(t)
        tol = pricing.tolerance(ctx.case, t, ctx.std)
        if not math.isfinite(c) or c > target + tol or c >= c_theirs:
            continue
        if any(same(t, s) for s in own) or not ctx.ok(t):
            continue
        out.append((label, t))
    if not out and last_sheets:
        return [(label, t) for label, t in last_sheets if ctx.ok(t)]
    return out


def no_regress(ctx, sheets, supplier_costs):
    """R12.10: never send a sheet that costs us as much as one the supplier already offered (within
    0.1 %). Returns the sheets that are left (maybe none)."""
    if not supplier_costs:
        return sheets
    best = min(supplier_costs)
    return [(label, t) for label, t in sheets if ctx.c(t) < (1 - REGRESS_TOL) * best]


def describe_order(field, values):
    return order(field, values)


def completed(ctx, terms):
    return closing_terms(ctx.case, terms, ctx.std)

"""Settling the heavy terms one at a time (R13.1-R13.5), from the MESO agent - with its two failures
fixed (R13.3 reopen a costly lock, R13.4 a step needs a choice).

After coverage is set (R12.2) the remaining non-price terms are ranked by how many EUR they move C,
the playbook's terms first; terms under MIN_WEIGHT of C are skipped, at most MAX_STEPS are kept.
Each step message varies ONE term across up to three packages that all cost us the same C (R13.8);
the value the supplier answers with is locked and the next message varies the next term. When
every term is locked only price is left, and section 6's sheets take over.

Judgement call: payment days, when they are a step term, go first - so the first menu is also the
payment probe of R12.7 and message 1 varies a single term as R13.1 asks.
"""

from collections import Counter

from .sheets import priced, structure_floor
from .terms import COVERAGE, complete, key

MAX_STEPS = 3
MIN_WEIGHT = 0.002  # R13.1: a term that moves C by less than 0.2 % is not worth a round
REOPEN_SHARE = 0.01  # R13.3: a lock costing us 1 % of C against the term's best option is stepped again
MAX_PER_TERM = 2


class Steps:
    """The step plan of one thread."""

    def __init__(self):
        self.order = None  # the terms worth a step, in order (fixed at the first move)
        self.weights = {}
        self.history = {}  # index of our message -> the term it varied, "price" or a one-off kind
        self.skipped = set()  # terms that had no credible choice (R13.4)

    # -- ranking ----------------------------------------------------------------------------------
    def rank(self, ctx, base):
        """R13.1: the non-price, non-coverage terms by EUR weight, the playbook's first."""
        if self.order is not None:
            return self.order
        price = ctx.their_price
        c_base = ctx.c({**base, "unit_price": price})
        first = list((ctx.playbook or {}).get("first") or [])
        weights = []
        for f in ctx.case["negotiable"]:
            if f == "unit_price" or f in COVERAGE:
                continue
            opts = ctx.allowed(f, base)
            if len(opts) < 2:
                continue
            costs = [ctx.c({**base, f: o, "unit_price": price}) for o in opts]
            w = max(costs) - min(costs)
            if w >= MIN_WEIGHT * c_base:
                weights.append((w, f))
                self.weights[f] = w
        weights.sort(key=lambda x: (x[1] != "payment_days", first.index(x[1]) if x[1] in first else len(first), -x[0]))
        self.order = [f for _, f in weights[:MAX_STEPS]]
        return self.order

    # -- what is settled --------------------------------------------------------------------------
    def counts(self):
        return Counter(v for v in self.history.values() if v not in ("price",))

    def locked(self, ctx, events):
        """After each step, the value of its term the supplier answered with (our first package's value
        if it answered without one, or with one that breaks a must-have). A term stepped only once whose
        answer costs us more than REOPEN_SHARE of C against its best option stays open (R13.3)."""
        out = {}
        mine = [i for i, m in enumerate(events) if m.get("from") == "buyer"]
        for k, field in sorted(self.history.items()):
            if field not in ctx.case["negotiable"] or k >= len(mine):
                continue
            i = mine[k]
            ours = ((events[i].get("term_sheets") or [{}])[0].get("terms") or {}).get(field)
            reply = next((m for m in events[i + 1 :] if m.get("from") != "buyer"), None)
            if reply is None:
                continue
            sheets = reply.get("term_sheets") or []
            theirs = sheets[0]["terms"].get(field, ctx.std.get(field, ours)) if sheets else ours
            out[field] = theirs if ctx.ok({**ctx.their, **out, field: theirs}) else ours
        counts = self.counts()
        t = complete(ctx.case, {**ctx.their, **out}, ctx.std)
        c_t = ctx.c(t)
        for field in [f for f in out if counts[f] == 1]:
            costs = [ctx.c({**t, field: o}) for o in ctx.allowed(field, t)]
            if costs and c_t - min(costs) > REOPEN_SHARE * c_t:
                del out[field]
        return out

    def revealed(self, ctx, latest_msg, alternatives):
        """R13.5: a term the supplier priced itself - its latest e-mail offers two packages that differ
        in that term only (its sheet and an alternative sheet or "Alternatively" line) - locked at the
        value that costs us less at the supplier's own prices."""
        sheets = [ts.get("terms") or {} for ts in latest_msg.get("term_sheets") or []]
        if not sheets:
            return {}
        main = complete(ctx.case, sheets[0], ctx.std)
        best = {}
        for alt in [*sheets[1:], *alternatives]:
            full = complete(ctx.case, {**sheets[0], **alt}, ctx.std)
            diff = [f for f in ctx.case["negotiable"] if f != "unit_price" and key(full.get(f)) != key(main.get(f))]
            if len(diff) != 1 or diff[0] in COVERAGE or not ctx.ok(full):
                continue
            f = diff[0]
            for c, value in ((ctx.c(main), main[f]), (ctx.c(full), full[f])):
                if f not in best or c < best[f][0]:
                    best[f] = (c, value)
        return {f: v for f, (_, v) in best.items()}

    def next_field(self, ctx, base, locked, asks=()):
        """The term this message varies: an asked-for step term first, else the next of the order that
        is not locked, not skipped and stepped at most once before; None once only price is left."""
        counts = self.counts()
        order = self.rank(ctx, base)
        for f in [*[a for a in asks if a in order], *order]:
            if f in locked or f in self.skipped or counts[f] >= MAX_PER_TERM:
                continue
            if len(ctx.allowed(f, base)) > 1:
                return f
        return None

    def only_price(self, ctx, base, locked):
        return self.next_field(ctx, base, locked) is None

    # -- the packages of one step -----------------------------------------------------------------
    @staticmethod
    def option_order(ctx, field, base, asked=None):
        """R13.2: the best option for us first, then the one the supplier asked for, its current value,
        the middle option, the rest - three at most, each a different package."""
        opts = ctx.allowed(field, base)
        price = ctx.their_price
        ranked = sorted(opts, key=lambda o: ctx.c({**base, field: o, "unit_price": price}))
        theirs = complete(ctx.case, ctx.their, ctx.std).get(field)
        wanted = [ranked[0], *([asked] if asked is not None else []), theirs, ranked[len(ranked) // 2], *ranked]
        picks = []
        for o in wanted:
            if any(key(o) == key(x) for x in opts) and all(key(o) != key(p) for p in picks) and len(picks) < 3:
                picks.append(o)
        return picks

    def packages(self, ctx, field, base, target, floor_price, asked=None):
        """The step's packages at `target`, each credible (at or above its structure's floor, under the
        supplier's price). R13.4: fewer than two is no step - [] then."""
        out = []
        for o in self.option_order(ctx, field, base, asked):
            combo = {**base, field: o}
            sheet = priced(ctx, combo, target, structure_floor(ctx, combo, base, floor_price))
            if sheet and ctx.ok(sheet) and all(sheet != s for _, s in out):
                out.append((f"{field}={o if not isinstance(o, dict) else o.get('deadband_pct')}", sheet))
        return out if len(out) >= 2 else []

    def record(self, k, kind):
        self.history[k] = kind


def repeats(new_sheets, last_sheets):
    """R13.7: the next message would only repeat our last sheets."""
    if not last_sheets or not new_sheets:
        return False
    a = sorted(key(t) for t in new_sheets)
    b = sorted(key(t) for t in last_sheets)
    return a == b

"""When to close (section 7), the accept ladder (R12.11) and the close guards of DualAgent and
TeamAgent (R11.17-R11.18, R12.12-R12.13, R12.15, R13.13). Pure functions over `View`s - one per live
supplier thread - so the rules are testable on recorded negotiations without the arena.

Accept the cheapest sheet that keeps the must-haves and beats the alternative when the supplier
agreed (R7.1), made a final offer (R7.2), its offer meets our next target - unless it is still
moving with more than 3 rounds left (R7.3) - its offer is as good as what we last offered (R7.4), at
most one round is left (R7.5), or the planned rounds are over (R7.6). Walk away only when nothing on
the table is acceptable and every thread is at a final offer or out of rounds. No deadlock close and
no walk-risk close.
"""

from dataclasses import dataclass, field

EARLIER_SHARE = 0.001  # R12.11: earlier IDs cheaper by 0.1 %+ go before the latest ones
MAX_EARLIER = 3
REVISIT_SHARE = 0.003  # R12.13: an earlier sheet 0.3 % cheaper is offered back once
COVERAGE_SHARE = 0.01  # R11.17: uncovered need over 1 % of C never "meets our target"
TARGET_TOL = 0.002  # R7.3
LAST_TOL = 0.001  # R7.4
MOVING_ROUNDS = 3  # R5.4 / R7.3
HOPELESS_SHARE, HOPELESS_MOVE = 0.08, 0.01  # R12.15
DEAR_SHARE = 0.25  # R8.2
STALL_TOL = 0.001


@dataclass
class Row:
    """One sheet the supplier put on the table: a main sheet or an alternative."""

    id: str
    terms: dict
    c: float  # our C with the margin charge where the goal has one
    valid: bool  # keeps the must-haves and beats the alternative
    latest: bool  # in its latest e-mail
    main: bool = True
    reply: int = 0  # which of its replies (0 = the opening)
    uncovered: float = 0.0  # EUR of uncovered need (and its risk) in C


@dataclass
class View:
    """One live supplier thread, as the close rules see it."""

    sid: str
    status: str | None
    left: int  # messages we may still send
    sent: int  # our messages that reached it
    rows: list = field(default_factory=list)
    target: float | None = None  # our next target C
    last_target: float | None = None  # the target of our last offer
    moving: bool = False  # still conceding more than 0.4 % of C (R5.4)
    only_price: bool = False  # every step term settled (R13.13)
    planned_over: bool = False  # H + 2 offers made (R7.6)
    close_gap: float = 0.005
    replies_c: list = field(default_factory=list)  # C of its best sheet per reply, oldest first
    earlier_used: bool = False  # R12.13 offer-back already made
    repair_used: bool = False  # R12.12 repair already made
    restore_used: bool = False  # R11.17 coverage message already made
    last_step_share: float = 0.0  # how far it moved in its last reply, share of C

    @property
    def latest_rows(self):
        return [r for r in self.rows if r.latest]

    @property
    def best(self):
        """Its cheapest valid sheet of the latest e-mail (R3.1), else None."""
        ok = [r for r in self.latest_rows if r.valid]
        return min(ok, key=lambda r: r.c) if ok else None

    @property
    def c_now(self):
        rows = self.latest_rows
        return min((r.c for r in rows if r.valid), default=min((r.c for r in rows), default=float("inf")))


@dataclass
class Close:
    kind: str  # accept | walk | idle | offer_back | repair | restore
    reason: str
    sid: str | None = None
    sheet_id: str | None = None
    candidates: list = field(default_factory=list)  # the accept ladder [(sid, sheet_id)]
    terms: dict | None = None  # offer_back / repair / restore: the terms to send


def blocked(views, row, sid):
    """R11.18: never accept a bidder's unchanged opening while a cheaper rival sheet is on the table."""
    if row.reply != 0 or len(views) < 2:
        return False
    return any(r.valid and r.latest and r.c < row.c for v in views.values() if v.sid != sid for r in v.rows)


def ladder(views):
    """R12.11: every valid sheet ever offered in every live thread, cheapest first; up to MAX_EARLIER
    earlier IDs (cheaper by EARLIER_SHARE+) before the latest ones. A refused accept changes nothing."""
    rows = sorted(
        (r.c, not r.latest, not r.main, v.sid, r.id)
        for v in views.values()
        for r in v.rows
        if r.valid and not blocked(views, r, v.sid)
    )
    now = [x for x in rows if not x[1]]
    if not now:
        return []
    earlier = [x for x in rows if x[1] and x[0] < now[0][0] * (1 - EARLIER_SHARE)][:MAX_EARLIER]
    return list(dict.fromkeys((x[3], x[4]) for x in sorted(earlier + now)))


def accept(views, reason):
    cands = ladder(views)
    if not cands:
        return None
    return Close("accept", reason, cands[0][0], cands[0][1], cands)


def walk(views, reason):
    sid = next(iter(views)) if views else None
    return Close("walk", reason, sid)


def earlier_cheaper(view):
    """R12.13: once per thread, an earlier valid sheet of its own 0.3 % cheaper than the best of its
    latest e-mail - its terms go back as our sheet."""
    if view.earlier_used or view.left <= 0 or view.status == "final_offer":
        return None
    now = [r.c for r in view.latest_rows if r.valid] or [r.c for r in view.latest_rows]
    before = [r for r in view.rows if not r.latest and r.valid]
    if not now or not before:
        return None
    r = min(before, key=lambda r: r.c)
    return r if r.c <= (1 - REVISIT_SHARE) * min(now) else None


def stalled(view):
    """No cheaper offer over its last three replies after 3+ of our messages (R12.13)."""
    cs = view.replies_c
    if view.sent < 3 or len(cs) < 3:
        return False
    return cs[-1] >= cs[-3] - max(1.0, STALL_TOL * cs[-3])


def covered(view, row):
    return row is not None and row.uncovered <= COVERAGE_SHARE * row.c


def ends(view):
    """At a final offer or out of rounds: nothing more will come from this thread."""
    return view.status in ("final_offer", "agreed") or view.left <= 0


def hopeless(views, view):
    """R12.15 / R8.2 (RFQ, 3+ live bidders): far dearer than the best and not moving - stop writing."""
    if len(views) < 3 or view.best is None:
        return False
    best_all = min((v.best.c for v in views.values() if v.best), default=None)
    if best_all is None:
        return False
    if view.best.c > (1 + HOPELESS_SHARE) * best_all and view.last_step_share < HOPELESS_MOVE and len(view.replies_c) >= 3:
        return True
    return view.best.c > (1 + DEAR_SHARE) * best_all and view.sent >= 2


def decide(views, sid, must_close=False):
    """The close rule for thread `sid`, or None (negotiate on). `views`: every live thread."""
    v = views[sid]
    rfq = len(views) > 1
    cands = ladder(views)
    best_sid = cands[0][0] if cands else None
    heard = all(x.sent >= 1 for x in views.values())  # R11.18: every bidder has had an offer
    may_accept = bool(cands) and (not rfq or heard)

    if must_close:  # R11.14: closed by the clock
        return accept(views, "case clock: close") or walk(views, "case clock: nothing acceptable")

    if v.status == "final_offer":  # R12.12: its last word - accept at once, anything more makes it walk
        if cands and (not rfq or best_sid == sid or all(ends(x) for x in views.values())):
            return accept(views, "final offer")
        if cands and rfq:
            return Close("idle", "final offer, a rival is better", sid)
        if not v.repair_used and v.left > 0 and v.rows:
            return Close("repair", "final offer breaks a must-have or loses to the alternative - one repair", sid)
        if all(ends(x) for x in views.values()):
            return walk(views, "nothing acceptable, every thread at its end")
        return Close("idle", "final offer, nothing acceptable here", sid)

    if v.status == "agreed":  # R7.1, R12.13
        if (r := earlier_cheaper(v)) is not None:
            return Close("offer_back", "its earlier offer was cheaper than the agreed sheet", sid, r.id, terms=r.terms)
        if may_accept and (not rfq or best_sid == sid):
            return accept(views, "agreed to our terms")

    if stalled(v) and best_sid == sid:  # R12.13
        if (r := earlier_cheaper(v)) is not None:
            return Close("offer_back", "stalled: back to its own earlier, cheaper offer", sid, r.id, terms=r.terms)
        if may_accept:
            return accept(views, "stalled: no more movement")

    best = v.best
    if best is not None and v.sent >= 1 and v.target is not None:
        meets = best.c <= v.target * (1 + TARGET_TOL) and not (v.moving and v.left > MOVING_ROUNDS)
        if meets and not covered(v, best):  # R11.17
            if v.left > 0 and not v.restore_used:
                return Close("restore", "meets the target but leaves need uncovered", sid, best.id, terms=best.terms)
            meets = False
        if meets and may_accept and best_sid == sid:
            return accept(views, "its offer meets our next target")
        if v.only_price and best.c <= v.target * (1 + v.close_gap) and covered(v, best) and may_accept and best_sid == sid:
            return accept(views, "small gap, only price left")  # R13.13
    if best is not None and v.last_target is not None and best.c <= v.last_target * (1 + LAST_TOL):
        if covered(v, best) and may_accept and best_sid == sid:
            return accept(views, "its offer is as good as what we last offered")  # R7.4

    if (v.left <= 1 and not rfq) or all(x.left <= 1 for x in views.values()):  # R7.5
        if may_accept or (cands and rfq):
            return accept(views, "at most one round left")
        if all(ends(x) or x.left <= 1 for x in views.values()):
            return walk(views, "nothing acceptable and no rounds left")
    if all(x.planned_over for x in views.values()) and may_accept:  # R7.6
        return accept(views, "the planned rounds are over")
    if rfq and hopeless(views, v):
        return Close("idle", "far dearer than the best bidder and not moving", sid)
    if v.left <= 0:
        return Close("idle", "no messages left in this thread", sid) if rfq else (
            accept(views, "no messages left") or walk(views, "no messages left, nothing acceptable"))
    return None

"""The e-mail around the term sheets (section 9, R12.20-R12.21, R13.14-R13.15).

The model writes words only (R9.1): salutation, opening, the keys of the arguments it picks, bridge,
question, closing. Code puts in everything that must match the numbers - the arguments word for word,
its own sentences (the weighted cost arithmetic, a volume commitment, an earlier offer taken up, the
rival's offer in an RFQ) and the options paragraph built from the term sheets themselves (`describe`)
- then lints what the model wrote: no leaks, no figure that is not in the material, no data ID, no
unknown ID, no repeated claim (R13.15, R9.7, R12.20). Without the model (late, failed, or no time
left) the tactic's code-written lines carry the e-mail, with the two best arguments (R9.5, R10.1).
"""

import base64
import json
import re

from .. import writing
from .prose import sentences

ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr):[\w.:@#/-]*\w")
COMPANY_RE = re.compile(
    r"^(?:[^,]{2,60},\s*)?(.+?\b(?:GmbH(?: & Co\. KG)?|KG|AG|SE|Ltd\.?|Kft\.?|s\.r\.o\.|Sp\. z o\.o\.|S\.A\.|S\.p\.A\.|"
    r"Srl|S\.r\.l\.|B\.V\.|N\.V\.|Inc\.?|LLC|AB|Oy|A/S|e\.K\.|OHG|GbR)\.?)\s*$"
)
VOLUME_ASK = re.compile(r"which volume|binding (?:higher )?volume|volume commitment|volume can you commit|"
                        r"exact volume|annual requirement", re.I)  # fmt: skip
ASK_DATA = re.compile(r"send (?:us )?the data|which figures|share the (?:detailed )?(?:forecast )?data|provide the "
                      r"(?:specific )?(?:forecast|data|figures|volume data)|data behind|verify (?:this|it|these)", re.I)  # fmt: skip
SIGNATURE = writing.SIGNATURE

SYSTEM = """You write e-mails for the purchasing team of Hollerau Pumpenwerke GmbH, a German pump maker,
to an industrial supplier. The term sheets of this e-mail are already decided by code; you write the
words around them.

Return ONE JSON object and nothing else:
{"salutation": "...", "opening": "...", "claims": ["key", ...], "bridge": "...", "question": "...", "closing": "..."}

- salutation: "Dear <name>," only if that person's name appears in the supplier's e-mails; otherwise
  "Dear colleagues at <short company name>,".
- opening (1-2 sentences): answer what they last wrote - name their point, acknowledge what is fair in
  it, thank them for a move they made. Never ignore their argument; never repeat one they rejected.
- claims: 0-3 keys from ARGUMENTS, best first - only those that fit this supplier and this moment. On
  our first e-mail use the strongest one or two. They are inserted word for word; do not restate them.
- bridge (1-2 sentences, no figures): why the options make sense for both sides, in terms of what this
  supplier cares about (PROFILE). Several options: say we are flexible on the term they vary and ask
  which works best. If THE MOVE says they asked for a term, name it and point to the option that gives it.
- question (1 sentence): one question from QUESTIONS, or "".
- closing (1 sentence): warm and professional, in the tone the PROFILE asks for.

Follow THE MOVE: if we hold, say so; do not thank them for a step they did not make. Tone may carry
honest feeling grounded in facts (disappointment at no movement, the history between the companies).
Never invent hardship, never threaten, no filler ("balance", "mutual benefit", "synergy", "win-win").
Never promise documents, data, calls or meetings we would send or hold later - this e-mail is all we send.

Rules: plain business English, short sentences, 70-130 words for all parts together. No figures,
prices, percentages or data IDs in your own text - code adds them. Never mention deadlines, urgency,
budgets, that we lack alternatives, our internal costs, or any scoring. No placeholders, no sign-off."""


# --- the options paragraph (R13.14) ----------------------------------------------------------------
def describe(terms, fields):
    """A term sheet in words - code writes it from the sheet, so prose and sheets never disagree."""
    out = []
    for f in fields:
        v = terms.get(f)
        if v is None and f != "index_clause":
            continue
        if f == "unit_price":
            out.append(f"EUR {v:,.2f} per unit")
        elif f == "payment_days":
            out.append(f"payment {v} days net")
        elif f == "effective_date":
            out.append(f"new price from {v}")
        elif f == "contract_months":
            out.append("a single order" if v == 0 else f"{v}-month agreement")
        elif f == "volume_per_year":
            out.append(f"{v:,} units per year")
        elif f == "lead_time_days":
            out.append(f"lead time {v} days")
        elif f == "index_clause":
            out.append("fixed price, no index clause" if not v else
                       f"index clause on {v['series']} ({v['material_share']:.0%} material share, "
                       f"{v['deadband_pct']:g}% deadband, base {v['base_month']})")  # fmt: skip
        elif f == "ppm_commitment":
            out.append(f"quality commitment {v} ppm")
        elif f == "chargeback_eur_per_complaint":
            out.append(f"EUR {v:g} chargeback per complaint")
        elif f == "incoterm":
            out.append(f"Incoterm {v}")
        elif f == "tooling_eur":
            out.append(f"tooling EUR {v:,.0f}")
        else:
            out.append(f"{f.replace('_', ' ')} {v}")
    return ", ".join(out)


def shown_fields(case, sheets, theirs):
    """The terms the options paragraph spells out: those that differ between our sheets, then those
    that differ from the supplier's sheet, then the rest - every negotiable term (R13.14)."""

    def k(v):
        return json.dumps(v, sort_keys=True, default=str)

    fields = [f for f in case["negotiable"] if f != "unit_price"]
    varying = [f for f in fields if len({k(s.get(f)) for s in sheets}) > 1]
    differ = [f for f in fields if sheets and k(sheets[0].get(f)) != k((theirs or {}).get(f))]
    return ["unit_price", *dict.fromkeys(varying + differ + fields)]


def options_paragraph(case, sheets, theirs):
    fields = shown_fields(case, sheets, theirs)
    labelled = [describe(t, fields) for t in sheets]
    if not labelled:
        return ""
    if len(labelled) == 1:
        return f"We propose: {labelled[0]}."
    lines = [f"Option {'ABC'[i]}: {text}." for i, text in enumerate(labelled)]
    return "We can offer either of these packages - please choose the one that suits you better:\n" + "\n".join(lines)


# --- who we write to (R9.6) ---------------------------------------------------------------------
def company(name_from_data, events):
    """The supplier's name: from the data, else its subject ("Quote from X:") or signature - never the
    bare supplier ID."""
    if name_from_data:
        return name_from_data
    for m in events:
        if m.get("from") == "buyer":
            continue
        if found := re.search(r"Quote from (.+?):", m.get("subject") or ""):
            return found.group(1).strip()
        for line in reversed((m.get("body") or "").splitlines()):
            if found := COMPANY_RE.match(line.strip()):
                return found.group(1).strip()
    return "your team"


# --- questions (R9.4) -----------------------------------------------------------------------------
BREAKDOWN_Q = "Could you share a cost breakdown for this part - material, conversion, overhead?"
TYPE_Q = {
    "quality": "Could you send us the 8D report with root cause and containment for the recent complaints?",
    "capacity": "Could you send a delivery schedule with the monthly quantities you can commit to?",
    "rfq": "What is the shortest lead time you could commit to, and is there a cheaper design or material variant?",
    "price_increase": "Which cost elements of this part have actually risen since our last price agreement?",
    "renewal": "Which volume or contract length would let you improve the price further?",
    "bundling": "Which further parts or volumes would make a bundle more attractive for you?",
    "raw_material": "Which base month and deadband would you consider fair for an index clause?",
}


def _gist(q):
    return " ".join(re.findall(r"[a-z]+", str(q).lower())[:7])


def questions(case, events, profile_questions=()):
    """The questions not asked yet, in order: a cost breakdown once (unless asked or received), the
    case type's question, the profile's."""
    ours = " ".join(m.get("body", "") or "" for m in events if m.get("from") == "buyer").lower()
    got = " ".join(a.get("name", "") for m in events for a in m.get("attachments") or []).lower()
    out = []
    if "breakdown" not in ours and "breakdown" not in got:
        out.append(BREAKDOWN_Q)
    if (q := TYPE_Q.get(case.get("type"))) and _gist(q) not in " ".join(re.findall(r"[a-z]+", ours)):
        out.append(q)
    for q in profile_questions or []:
        if _gist(q) and _gist(q) not in " ".join(re.findall(r"[a-z]+", ours)):
            out.append(str(q))
    return out


def pick_question(raw, allowed):
    """The model's question if it is one of `allowed` (by its words), else None: one per e-mail, never
    repeated (R9.4)."""
    words = set(re.findall(r"[a-z]{4,}", str(raw or "").lower()))
    if not words:
        return None
    for q in allowed:
        qw = set(re.findall(r"[a-z]{4,}", q.lower()))
        if qw and len(words & qw) / len(qw) >= 0.4:
            return str(raw).strip()
    return None


# --- the stance (R9.3) ------------------------------------------------------------------------------
def stance(first, hold, moved_pct):
    if first:
        return "We open: our options are ambitious; give the reasons, not apologies."
    if hold:
        if moved_pct > 0.2:
            return ("We HOLD our position: they are still coming down. Acknowledge their step briefly, then say "
                    "clearly that the price is still too high and why.")  # fmt: skip
        return ("We HOLD our position because they did not move. Polite but firm; do not thank them for "
                "flexibility they did not show; give one concrete reason or ask what would let them move.")  # fmt: skip
    return "We make a modest step - this costs us and we expect a step back."


# --- code sentences --------------------------------------------------------------------------------
def weighted_sentence(intel):
    """R11.4: the cost-share arithmetic by the supplier's own figures, or None."""
    if intel is None:
        return None
    shared = [d for d in intel.cost_drivers if d.get("share_pct") is not None]
    if not shared or intel.cost_impact_pct is None or intel.asked_pct is None or (intel.cost_gap_pct or 0) <= 1.0:
        return None
    items = ", ".join(f"{d.get('series') or d['name']} {d['change_pct']:+.1f}% at {d['share_pct']:g}% of your cost"
                      for d in shared)  # fmt: skip
    return (f"By the figures you gave us - {items} - the weighted effect on the price is about "
            f"{intel.cost_impact_pct:+.1f}%, not the {intel.asked_pct:g}% you ask for.")  # fmt: skip


def commitment(sheet):
    """R13.15: our answer to "which volume can you commit to?", from our own sheet."""
    v, m = sheet.get("volume_per_year"), sheet.get("contract_months")
    if v is None and m is None:
        return None
    parts = [f"{v:,} units per year" if v else None, f"over {m} months" if m else None]
    return "We can commit to " + " ".join(p for p in parts if p) + ", as set out in the term sheets."


def rival_line(price, offer_id):
    """R12.14: the cheapest valid rival offer, as a checkable claim."""
    return f"A competing supplier has offered EUR {price:.2f} per unit ({offer_id})."


# --- the prompt (R9.2) -------------------------------------------------------------------------------
def render(case, sid, events, plan, profile, intel, feedback, args, allowed_questions, tactic, extras, company_name):
    last = next((m for m in reversed(events) if m.get("from") != "buyer"), {})
    ours = [m for m in events if m.get("from") == "buyer"]
    prof = {k: profile.get(k) for k in ("persona", "tone", "pressures", "wants", "avoid", "angle") if profile.get(k)}
    view = {}
    if intel is not None:
        view = {"constraints": intel.constraints, "lever_hints": intel.lever_hints, "their_questions": intel.questions,
                "relationship_style": intel.relationship_style}  # fmt: skip
    attachments = "\n".join(f"[their attachment {a.get('name')}]\n{(a.get('text') or '')[:1200]}"
                            for a in last.get("attachments") or [] if not (a.get("name") or "").startswith("quote"))  # fmt: skip
    move = (f"message {len(ours) + 1} in this thread. "
            + (f"Since our last e-mail they moved {plan['moved_pct']:.1f}% toward us. " if ours else "")
            + plan["stance"] + " " + plan.get("note", ""))  # fmt: skip
    parts = [
        f"CASE: {case.get('title')} ({case.get('type')}). Supplier: {company_name}.",
        f"PROFILE: {json.dumps(prof, ensure_ascii=False)}" if prof else "",
        f"TACTIC: {tactic.name} - {tactic.style}",
        f"WHAT OUR ANALYST SEES: {json.dumps(view, ensure_ascii=False, default=str)}" if view else "",
        f"THEIR LAST E-MAIL (from {last.get('from')}, status {last.get('status')}, subject {last.get('subject')!r}):\n"
        f"{(last.get('body') or '')[:2500]}",
        attachments,
        f"HOW OUR ARGUMENTS CHECKED OUT SO FAR: {json.dumps(feedback)}" if feedback else "",
        "OUR LAST E-MAILS (oldest first):\n" + "\n---\n".join((m.get("body") or "")[:700] for m in ours[-2:])
        if ours else "This is our first reply to their quote.",
        f"THE MOVE: {move}\nThe options (code inserts them after your bridge):\n{plan['options']}",
        f"CODE SENTENCES (already in the e-mail, do not repeat): {' '.join(extras)}" if extras else "",
        "ARGUMENTS ([key] sentence - note; answer with the keys only):\n"
        + ("\n".join(f"[{a.key}] {a.sentence} - {a.note}" for a in args[:6]) or "(none - write without data)"),
        "QUESTIONS (pick one or none):\n" + ("\n".join(allowed_questions) or "(none)"),
    ]
    return "\n\n".join(p for p in parts if p)


# --- assembly ---------------------------------------------------------------------------------------
def code_parts(tactic, question):
    return {"salutation": "", "opening": tactic.opening, "claims": None, "bridge": tactic.bridge,
            "question": question or "", "closing": tactic.closing, "fallback": True}  # fmt: skip


def pick_claims(parts, args, n_fallback=2):
    by_key = {a.key: a for a in args}
    if parts.get("fallback") or not parts.get("claims"):
        keys = [a.key for a in args if a.ids][:n_fallback]  # R9.5: even a fallback carries the two best
    else:
        keys = parts.get("claims") or []
    picked = []
    for k in keys:
        if (c := writing.match_key(k, by_key)) and c not in picked and len(picked) < 3:
            picked.append(c)
    return picked


def drop_repeated(body, used_ids):
    """R12.20: drop a sentence whose IDs were all cited before (it would come back `duplicate`)."""
    out = []
    for para in body.split("\n\n"):
        keep = []
        for line in para.split("\n"):
            parts = []
            for s in sentences(line) or [line]:
                ids = ID_RE.findall(s)
                if not ids or not all(i in used_ids for i in ids):
                    parts.append(s)
            if parts:
                keep.append(" ".join(parts))
        if keep:
            out.append("\n".join(keep))
    return "\n\n".join(out)


def compose(case, events, sheets, theirs, parts, args, material, company_name, extras=(), analysis=(),
            used_ids=(), known=lambda ref: True, allowed_questions=()):  # fmt: skip
    """The e-mail body from the model's parts and code's sentences: (body, picked claims, dropped)."""
    options = options_paragraph(case, sheets, theirs)
    picked = [c for c in pick_claims(parts, args) if not (analysis and c.key == "summary:indices")]
    numbers = writing.allowed(material, *(a.sentence for a in args), options, *extras, *analysis)
    dropped = []
    clean = {k: writing.lint(parts.get(k), numbers, dropped) for k in ("opening", "bridge", "closing")}
    q = parts.get("question") if parts.get("fallback") else pick_question(parts.get("question"), allowed_questions)
    question = writing.lint(q, numbers, dropped) if q else ""
    claims_text = " ".join(c.sentence + "".join(" " + e for e in c.extra) for c in picked)
    hello = writing.salutation(parts.get("salutation"), company_name, material)
    body = "\n\n".join(p for p in [
        hello, clean["opening"], " ".join(x for x in (*analysis, claims_text) if x),
        " ".join(x for x in (clean["bridge"], *extras) if x), options, question, clean["closing"], SIGNATURE,
    ] if p)  # fmt: skip

    def keep_known(m):
        return m.group(0) if known(m.group(0)) else ""

    body = re.sub(r"[ \t]*\(\s*[,;\s]*\)", "", ID_RE.sub(keep_known, body))
    body = drop_repeated(body, set(used_ids)).strip()[:8000]
    return body, picked, dropped


def data_attachment(events, body, fact):
    """R12.21: when the supplier asks for our figures, attach every ID we cited with its values."""
    last = next((m for m in reversed(events) if m.get("from") != "buyer"), {})
    if not ASK_DATA.search(str(last.get("body") or "")):
        return None
    mine = [str(m.get("body") or "") for m in events if m.get("from") == "buyer"]
    ids = list(dict.fromkeys(i for text in [body, *mine] for i in ID_RE.findall(text)))
    rows = [(i, f) for i in ids if (f := fact(i))]
    if not rows:
        return None
    lines = ["# Data behind our figures (Hollerau Pumpenwerke, Purchasing)", "", "| ID | data |", "|---|---|"]
    lines += [f"| {i} | {json.dumps(f, ensure_ascii=False, default=str)[:300]} |" for i, f in rows[:20]]
    content = base64.b64encode("\n".join(lines).encode("utf-8")).decode("ascii")
    return {"name": "our-figures.md", "type": "md", "content_b64": content}

"""What to compute from the case JSON before the first message (section 0.7).

  1  check the case file (`normalise`): every negotiable field but the price has options, no field is
     both fixed and negotiable, must-haves name real fields; values outside the practice ranges of
     section 0 are logged; values the API itself rules out fall back to defaults. Never crashes.
  2  C of every opening quote with the supplier's standard terms filled in, and C_alt
  3  coverage: does contract_months x volume_per_year cover the need over the horizon - and which
     option closes the gap and lowers C (R12.1-R12.2)
  4  the lever table (R12.3), the playbook row (R13.10), the anchor (R4, R13.12) and the floor (R6.5)
  5  the must-have filter every sheet and every accept passes through
  6  the clock: round_limit and, in the final, seconds_left

Judgement call on "fall back to defaults": the arena prices C with the case's own values, so a value
merely outside the practice range (e.g. an interest rate of 10 %) is used as given and logged; only a
value the API rules out (a horizon over 3 years, a negative price, a wrong type, a missing field) is
replaced by a default.
"""

import copy
import logging
import math
from dataclasses import dataclass, field

from ..cost import OPS, closing_terms, must_haves_ok, total_cost
from ..docs import standard_terms
from . import estimate as est_mod
from . import levers, playbook, pricing
from .clock import CaseClock
from .sheets import Ctx, cover, floor, repair
from .terms import COVERAGE, complete, uncovered_units

log = logging.getLogger("arena")

TERM_FIELDS = {
    "unit_price", "payment_days", "lead_time_days", "volume_per_year", "contract_months", "effective_date",
    "index_clause", "incoterm", "tooling_eur", "ppm_commitment", "chargeback_eur_per_complaint",
}  # fmt: skip
TYPES = {"price_increase", "renewal", "rfq", "bundling", "raw_material", "capacity", "quality"}
GOAL_RATES = {"leverage": (3, 1), "routine": (5, 2), "quality_first": (8, 2), "stabilise": (10, 4),
              "secure_supply": (25, 3)}  # fmt: skip  # (fallback_risk_pct, index_risk_pct)
# field: (practice range - log outside, API range - default outside, default)
BUYER_RANGES = {
    "need_per_year": ((3420, 94800), (1e-9, math.inf), None),
    "horizon_years": ((1, 2), (1e-9, 3), 1.0),
    "current_unit_price": ((4.20, 412.74), (0.0, math.inf), None),
    "fallback_unit_price": ((1.0, 1000.0), (0.0, math.inf), None),
    "interest_rate": ((0.08, 0.08), (0.0, 1.0), 0.08),
    "reference_payment_days": ((60, 60), (0, 120), 60),
    "need_lead_time_days": ((5, 59), (0, 3650), None),
    "late_cost_per_day": ((40, 2400), (0, math.inf), 0.0),
    "cost_per_defect": ((0, 780), (0, math.inf), 0.0),
    "sustainable_margin_pct": ((0.5, 10), (0, 100), None),
    "relationship_eur_per_point": ((5000, 31920), (0, math.inf), None),
    "fallback_risk_pct": ((3, 25), (0, 1000), None),
    "index_risk_pct": ((1, 4), (0, 100), None),
}


def _num(v):
    return isinstance(v, int | float) and not isinstance(v, bool) and math.isfinite(v)


def normalise(case):
    """(a checked copy of the case, warnings). Never raises on a field outside section 0's ranges."""
    w = []
    c = copy.deepcopy(case) if isinstance(case, dict) else {}
    c.setdefault("case_id", "case:?")
    if c.get("type") not in TYPES:
        w.append(f"type {c.get('type')!r} unknown: levers from `negotiable`")
    neg = [f for f in c.get("negotiable") or [] if isinstance(f, str)]
    if "unit_price" not in neg:
        w.append("negotiable without unit_price: added")
        neg = ["unit_price", *neg]
    for f in neg:
        if f not in TERM_FIELDS:
            w.append(f"negotiable field {f!r} is not a known term")
    c["negotiable"] = neg
    c["fixed_terms"] = dict(c.get("fixed_terms") or {}) if isinstance(c.get("fixed_terms"), dict) else {}
    c["term_options"] = dict(c.get("term_options") or {}) if isinstance(c.get("term_options"), dict) else {}
    for f in [f for f in c["fixed_terms"] if f in neg]:
        w.append(f"{f} is both fixed and negotiable: negotiable wins")
        c["fixed_terms"].pop(f)
    for f in neg:
        if f != "unit_price" and not c["term_options"].get(f):
            w.append(f"negotiable {f} has no term_options: the supplier's standard value is sent")
    for f, opts in list(c["term_options"].items()):
        if not isinstance(opts, list):
            w.append(f"term_options[{f}] is not a list: dropped")
            c["term_options"].pop(f)
    rl = c.get("round_limit")
    if not (_num(rl) and rl >= 1):
        w.append(f"round_limit {rl!r}: default 10")
        c["round_limit"] = 10
    elif rl != 10:
        w.append(f"round_limit {rl} (practice: 10)")
    for k in ("suppliers", "parts", "refs"):
        c[k] = [x for x in c.get(k) or [] if isinstance(x, str)]
    if not c["suppliers"]:
        w.append("no suppliers in the case file")
    b = c["buyer"] = dict(c.get("buyer") or {})
    goal = b.get("category_goal")
    if goal not in playbook.PLAYBOOK:
        w.append(f"category_goal {goal!r} unknown: routine row")
    for k, ((lo, hi), (alo, ahi), default) in BUYER_RANGES.items():
        v = b.get(k)
        if v is None:
            if k in ("sustainable_margin_pct", "relationship_eur_per_point"):
                continue  # null = no margin charge (section 0.4)
            if k in ("fallback_risk_pct", "index_risk_pct"):
                b[k] = GOAL_RATES.get(goal, GOAL_RATES["routine"])[0 if k == "fallback_risk_pct" else 1]
                w.append(f"{k} missing: {b[k]} for the goal")
                continue
            if default is not None:
                b[k] = default
                w.append(f"{k} missing: default {default}")
            else:
                w.append(f"{k} missing")
            continue
        if not _num(v) or not (alo <= v <= ahi):
            fallback = default if default is not None else (
                GOAL_RATES.get(goal, GOAL_RATES["routine"])[0 if k == "fallback_risk_pct" else 1]
                if k in ("fallback_risk_pct", "index_risk_pct") else None)  # fmt: skip
            w.append(f"{k} = {v!r} is not allowed: default {fallback}")
            b[k] = fallback
        elif not (lo <= v <= hi):
            w.append(f"{k} = {v} outside the practice range {lo}-{hi}")
    if _num(b.get("horizon_years")):
        b["horizon_years"] = float(b["horizon_years"])
    if not _num(b.get("need_per_year")):
        b["need_per_year"] = c["fixed_terms"].get("volume_per_year") or 1
        w.append(f"need_per_year unusable: {b['need_per_year']}")
    if not _num(b.get("current_unit_price")) and _num(b.get("fallback_unit_price")):
        b["current_unit_price"] = b["fallback_unit_price"]
    if not _num(b.get("fallback_unit_price")) and _num(b.get("current_unit_price")):
        b["fallback_unit_price"] = b["current_unit_price"]
        w.append("fallback_unit_price unusable: the current price")
    if b.get("need_lead_time_days") is None:
        b["need_lead_time_days"] = c["fixed_terms"].get("lead_time_days") or 9999
    freight = b.get("freight_eur_per_unit") if isinstance(b.get("freight_eur_per_unit"), dict) else {}
    for inc in ("EXW", "FCA", "DAP"):
        if not _num(freight.get(inc)):
            freight[inc] = 0.0 if inc == "DAP" else max([x for x in freight.values() if _num(x)] or [0.0])
            w.append(f"freight for {inc} missing: {freight[inc]}")
    b["freight_eur_per_unit"] = freight
    if not isinstance(b.get("index_paths"), dict):
        b["index_paths"] = {}
    musts = []
    for m in b.get("must_haves") or []:
        if isinstance(m, dict) and m.get("field") in TERM_FIELDS and m.get("op") in OPS and "value" in m:
            musts.append(m)
        else:
            w.append(f"must-have {m!r} names no real field or operator: ignored")
    b["must_haves"] = musts
    alt = b.get("alternative") if isinstance(b.get("alternative"), dict) else {}
    if alt.get("kind") not in ("quote", "current_contract", "none"):
        w.append(f"alternative kind {alt.get('kind')!r}: treated as none")
        alt = {"kind": "none", "ref": None, "terms": {}}
    if alt.get("kind") != "none" and not _num((alt.get("terms") or {}).get("unit_price")):
        w.append("alternative without a price: treated as none")
        alt = {"kind": "none", "ref": None, "terms": {}}
    b["alternative"] = alt
    for msg in w:
        log.info("%s case check: %s", c.get("case_id"), msg)
    return c, w


def c_alternative(case):
    alt = case["buyer"].get("alternative") or {}
    if alt.get("kind") in (None, "none") or not (alt.get("terms") or {}).get("unit_price"):
        return math.inf
    try:
        return total_cost(case, alt["terms"])
    except Exception:
        return math.inf


@dataclass
class Opening:
    sid: str
    terms: dict
    std: dict
    c: float
    keeps_must_haves: bool
    estimate: est_mod.Estimate
    levers: list = field(default_factory=list)
    best_levers: dict = field(default_factory=dict)
    uncovered_units: float = 0.0
    coverage_fix: dict = field(default_factory=dict)  # {field: option} that closes the gap and lowers C
    coverage_saving: float = 0.0
    anchor: float | None = None  # price
    anchor_c: float | None = None
    floor: float | None = None


@dataclass
class Prep:
    case: dict
    warnings: list
    goal: str
    row: dict
    type_levers: list
    horizon: int
    c_alt: float
    openings: dict
    c_open: float
    clock: CaseClock

    def keeps_must_haves(self, terms, std=None):
        return must_haves_ok(self.case, terms, std)


def opening_terms(events):
    """The supplier's opening sheet from its first e-mail (term sheets, else the structured `terms`)."""
    for m in events or []:
        if m.get("from") == "buyer":
            continue
        sheets = m.get("term_sheets") or []
        if sheets and sheets[0].get("terms"):
            return sheets[0]["terms"]
        if m.get("terms"):
            return m["terms"]
    return {}


def anchor_price(case, ctx, their_price, best_quote, combo):
    """R4.1 + R4.2 + R13.12: the lowest of the goal's cut off the best quote, the current price (no
    increase at all in a price increase / raw material case), the fair price (should-cost / (1 -
    margin)) - lifted to the credibility limits: at most 25 % under its price, never under its full
    cost x 1.01, never under the price at which C stops falling."""
    b, row = case["buyer"], playbook.row(case)
    cands = [best_quote * (1 - playbook.anchor_cut(case))]
    current = b.get("current_unit_price")
    if case.get("type") in ("price_increase", "raw_material") and current and current < their_price:
        cands.append(current)
    est = ctx.est
    if est and est.point and est.source in ("should-cost", "breakdown"):
        margin = (b.get("sustainable_margin_pct") or 0) / 100 if row["fair"] is None else row["fair"]
        if margin:
            cands.append(est.point / (1 - margin))
    p = max(min(cands), their_price * (1 - playbook.MAX_ANCHOR_CUT))
    if est and est.full_cost and est.source in ("should-cost", "breakdown"):
        p = max(p, est.full_cost * 1.01)
    p = max(p, pricing.c_min_price(case, combo, ctx.std, ctx.supplier, p, their_price))
    return round(min(p, their_price), 2)


def prepare(case, threads=None, package=None, volatile=None, seconds_left=None, cash_short=None):
    """Section 0.7 for a case: with `threads` (the opening e-mails, quote PDFs read) every supplier's
    opening is priced; without them (before the session) a notional opening at the current price is
    used, so the preparation runs on the case file alone."""
    try:
        return _prepare(case, threads, package, volatile, seconds_left, cash_short or {})
    except Exception as e:  # a case file we cannot prepare must not cost the case: log and go minimal
        log.exception("%s: preparation failed (%s) - minimal defaults", (case or {}).get("case_id"), e)
        c, w = normalise(case)
        return Prep(c, [*w, f"preparation failed: {e}"], c["buyer"].get("category_goal") or "routine",
                    playbook.row(c), playbook.type_levers(c), playbook.horizon(c), c_alternative(c), {}, math.inf,
                    CaseClock(seconds_left))  # fmt: skip


def _prepare(case, threads, package, volatile, seconds_left, cash_short):
    c, warnings = normalise(case)
    b, row = c["buyer"], playbook.row(c)
    goal = b.get("category_goal") if b.get("category_goal") in playbook.PLAYBOOK else playbook.DEFAULT_GOAL
    c_alt = c_alternative(c)
    if threads:
        quotes = {sid: (opening_terms(ev), standard_terms(ev), ev) for sid, ev in threads.items()}
    else:
        price = b.get("current_unit_price") or b.get("fallback_unit_price") or 1.0
        quotes = {sid: ({"unit_price": price}, {}, []) for sid in c["suppliers"]}
    best_quote = min((q[0].get("unit_price") for q in quotes.values() if q[0].get("unit_price")), default=None)
    openings = {}
    for sid, (terms, std, events) in quotes.items():
        if not terms.get("unit_price"):
            warnings.append(f"{sid} quotes no price")
            continue
        est = est_mod.estimate(c, package, events, terms, cash_short=cash_short.get(sid, False))
        full = complete(c, terms, std)
        ctx = Ctx(c, std, est, full, row, volatile)
        cost = ctx.c(full)
        op = Opening(sid, full, std, cost, must_haves_ok(c, full, std), est)
        sup = ctx.supplier
        op.levers = levers.lever_table(c, full, std, sup)
        op.best_levers = levers.best_levers(c, full, std, sup)
        op.uncovered_units = uncovered_units(c, full, std)
        base = {k: v for k, v in repair(c, full, std).items() if k != "unit_price"}
        fixed = cover(ctx, base, full["unit_price"])
        op.coverage_fix = {f: fixed[f] for f in COVERAGE if f in fixed and fixed.get(f) != base.get(f)}
        if op.coverage_fix:
            op.coverage_saving = cost - ctx.c({**base, **op.coverage_fix, "unit_price": full["unit_price"]})
        combo = {**base, **op.coverage_fix}
        op.anchor = anchor_price(c, ctx, full["unit_price"], best_quote or full["unit_price"], combo)
        op.anchor_c = ctx.c({**combo, "unit_price": op.anchor})
        op.floor = round(floor(ctx), 2)
        openings[sid] = op
    valid = [o.c for o in openings.values() if o.keeps_must_haves]
    return Prep(c, warnings, goal, row, playbook.type_levers(c), playbook.horizon(c), c_alt, openings,
                min(valid, default=math.inf), CaseClock(seconds_left))  # fmt: skip


def summary(prep):
    """One line per supplier for the log."""
    out = [f"{prep.case['case_id']} {prep.case.get('type')}/{prep.goal}: C_alt "
           + (f"{prep.c_alt:,.0f}" if math.isfinite(prep.c_alt) else "none")]  # fmt: skip
    for o in prep.openings.values():
        lv = ", ".join(f"{f}->{levers.label(r['option'])} {-r['delta_eur']:,.0f}" for f, r in o.best_levers.items())
        out.append(f"  {o.sid}: C {o.c:,.0f} (price {o.terms['unit_price']}, must-haves {'ok' if o.keeps_must_haves else 'BROKEN'})"
                   f", uncovered {o.uncovered_units:,.0f} units, coverage {o.coverage_fix or '-'}, anchor {o.anchor}"
                   f", floor {o.floor}, estimate {o.estimate.source} {o.estimate.full_cost}; levers: {lv or '-'}")  # fmt: skip
    return "\n".join(out)


def closing(case, terms, std):
    return closing_terms(case, terms, std)

"""Play a case with one worker per supplier thread (R12.18, R13.16), ported from TeamAgent's
`team/runner.py`.

Every thread has its own 60-second clock and a supplier reply can take up to a minute, so each
thread answers as soon as its supplier has replied (R8.1). Network and API trouble never cost a case:
calls are retried, a send that may have landed is checked against the arena before it is repeated, a
worker never dies on an error, and a case is done only when the arena has ended the session. Close to
a Live Final wave's cap the accept ladder closes the case.

R13.16: a slow POST reads the reply from the thread (`RemoteTable.send`); an accept in an RFQ waits
for replies still in flight from other bidders (R12.16) - but never past 45 s after its own reply, so
a final offer that is the best on the table is accepted inside the 60 seconds; a refused accept
(`422`, the offer moved on) reloads the threads and decides again.
"""

import copy
import logging
import threading
import time

import httpx

from ..client import ArenaError
from ..play import CLOSE_BEFORE_CAP_S, MOVE_LIMIT_S, ROUND_MARGIN_S, closing_move, fetch_documents, live_threads, moves_left

log = logging.getLogger("arena")
RETRY_SLEEP_S = (1, 3, 5, 6, 6)
MAX_FAILURES = 3
ACCEPT_WAIT_S = 45.0  # R13.16: an accept waits for rival replies at most this long after its own reply


def retryable(e):
    if isinstance(e, httpx.TransportError):
        return True
    if isinstance(e, ArenaError):
        detail = str(e.detail)
        return e.status >= 500 or (e.status == 429 and "practice" not in detail and "open sessions" not in detail)
    return False


def call(fn, *args):
    for i, pause in enumerate((*RETRY_SLEEP_S, None)):
        try:
            return fn(*args)
        except Exception as e:
            if pause is None or not retryable(e):
                raise
            log.warning("retry %d after %s", i + 1, e)
            time.sleep(pause)


def safe_documents(table, message):
    try:
        return fetch_documents(table, message)
    except Exception as e:
        log.warning("attachment unreadable: %s", e)
        return message


def case_file(table, case_id):
    """The case file before the session opens, so the agent prepares without the clock (R1.3)."""
    if getattr(table, "case", None):
        return table.case
    for set_ in ("practice", "sandbox"):
        try:
            found = next((c for c in table.client.cases(set_) if c["case_id"] == case_id), None)
        except Exception:
            continue
        if found:
            return found
    return None


def play_case(table, case_id, agent, deadline=None):
    """Play one case to its end with `agent` (a SpecAgent). Returns the result."""
    pre = case_file(table, case_id)
    if pre is not None and hasattr(agent, "prime"):
        try:
            agent.prime(pre)
        except Exception:
            log.exception("%s: prime failed - going on without profiles", case_id)
    case, threads = call(table.open, case_id)
    if getattr(table, "done", None):
        return table.done
    for events in threads.values():
        for m in events:
            safe_documents(table, m)
    lock, close_lock, done, closing = threading.Lock(), threading.Lock(), threading.Event(), threading.Event()
    out, slowest = {}, [0.0]
    reply_at = {sid: time.monotonic() for sid in threads}
    inflight = {sid: False for sid in threads}
    agent.reply_at, agent.inflight = reply_at, inflight
    seconds_left = (deadline() if callable(deadline) else deadline) or None
    seconds_left = seconds_left - time.time() if seconds_left else (pre or {}).get("seconds_left")
    agent.prepare(case, threads, seconds_left)

    def cap():
        return deadline() if callable(deadline) else deadline

    def refresh(sid):
        try:
            messages = call(table.client.thread, table.session_id, sid)["messages"]
        except Exception as e:
            log.warning("%s %s: refresh failed: %s", case_id, sid, e)
            return
        messages = [safe_documents(table, m) for m in messages]
        with lock:
            threads[sid] = messages

    def ended():
        try:
            state = call(table.client.session, table.session_id)
        except Exception:
            return None
        return state if state.get("status") == "ended" else None

    def ladder(view):
        try:
            return agent.accept_candidates(case, view)
        except Exception:
            log.exception("%s: ladder failed", case_id)
            d = closing_move(case, view)
            a = d["message"]["action"]
            return [(d["supplier_id"], a["term_sheet_id"])] if a.get("type") == "accept" else []

    def close(decision):
        msg = decision["message"]
        with close_lock:
            if done.is_set():
                return True
            if msg["action"].get("type") != "accept":
                try:
                    out["result"] = call(table.close, decision["supplier_id"], msg)
                except ArenaError as e:
                    log.warning("%s: walk away failed: %s", case_id, e.detail)
                if out.get("result") or ended():
                    done.set()
                return done.is_set()
            candidates = decision.get("candidates") or [(decision["supplier_id"], msg["action"]["term_sheet_id"])]
            for rnd in range(2):
                for sid, oid in candidates[:4]:
                    try:
                        log.info("%s %s accept %s (%s)", case_id, sid, oid, decision.get("reason", ""))
                        out["result"] = call(table.close, sid, {"action": {"type": "accept", "term_sheet_id": oid}})
                        done.set()
                        return True
                    except ArenaError as e:
                        log.warning("%s: accept %s refused: %s", case_id, oid, e.detail)
                        if state := ended():
                            out["result"] = state.get("result") or table.result()
                            done.set()
                            return True
                if rnd == 0:  # the offer moved on: reload, decide again
                    for sid in {s for s, _ in candidates}:
                        refresh(sid)
                    with lock:
                        view = copy.deepcopy(threads)
                    candidates = ladder(view)
                    if not candidates:
                        break
            log.warning("%s: no accept went through - the case goes on", case_id)
            return False

    def send_safe(target, msg):
        with lock:
            mine = sum(m.get("from") == "buyer" for m in threads[target])
        for attempt in range(3):
            try:
                return table.send(target, msg)
            except ArenaError as e:
                if not retryable(e):
                    raise
            except httpx.TransportError as e:
                log.warning("%s %s: send failed (%s) - checking whether it landed", case_id, target, e)
            for _ in range(30):
                try:
                    t = call(table.client.thread, table.session_id, target)
                except Exception:
                    break
                held = t.get("messages") or []
                if sum(m.get("from") == "buyer" for m in held) <= mine:
                    break
                if held and held[-1].get("from") != "buyer":
                    return held[-1]
                time.sleep(2)
            time.sleep(RETRY_SLEEP_S[attempt])
        raise ArenaError(503, "send failed three times")

    def worker(sid, rank=0):
        failures, first = 0, True
        while not done.is_set() and failures < MAX_FAILURES:
            with lock:
                if sid not in live_threads(threads) or moves_left(case, threads[sid]) < 0:
                    return
                view = copy.deepcopy(threads)
            t0 = time.monotonic()
            c = cap()
            if c and time.time() > c - max(CLOSE_BEFORE_CAP_S, slowest[0] + ROUND_MARGIN_S):
                log.info("%s: the wave's cap is near - closing on the ladder", case_id)
                cands = ladder(view)
                close({"supplier_id": cands[0][0], "candidates": cands, "reason": "wave cap",
                       "message": {"action": {"type": "accept", "term_sheet_id": cands[0][1]}}}
                      if cands else closing_move(case, view))  # fmt: skip
                return
            try:
                d = agent.decide(case, view, sid)
            except Exception:
                log.exception("%s %s: decide failed - planned move", case_id, sid)
                try:
                    d = agent.fallback(case, view, sid)
                except Exception:
                    log.exception("%s %s: fallback failed", case_id, sid)
                    failures += 1
                    refresh(sid)
                    time.sleep(2)
                    continue
            if (took := time.monotonic() - t0) > MOVE_LIMIT_S * 0.75:
                log.warning("%s %s: decision took %.1fs", case_id, sid, took)
            if not d or d.get("idle"):
                return
            target, msg = d["supplier_id"], d["message"]
            if msg.get("action"):
                if msg["action"].get("type") == "accept" and len(live_threads(view)) > 1:
                    closing.set()  # R12.16: a rival reply may be on its way - but R13.16: inside 60 s
                    while any(busy for s, busy in inflight.items() if s != target) and \
                            time.monotonic() < reply_at.get(target, 0) + ACCEPT_WAIT_S:
                        time.sleep(0.5)
                    with lock:
                        view = copy.deepcopy(threads)
                    d = agent.accept(case, view) or d
                ok = close(d)
                closing.clear()
                if ok:
                    return
                failures += 1
                continue
            while closing.is_set() and not done.is_set():
                time.sleep(0.5)
            if done.is_set():
                return
            if first and rank:  # RFQ: calls on one session queue up - the most promising bidder first
                time.sleep(0.3 * rank)
            first, late = False, False
            inflight[target] = True
            agent.sent(target)
            try:
                reply = send_safe(target, msg)
            except ArenaError as e:
                if done.is_set():
                    return
                if e.status == 409:
                    late = True
                    try:
                        reply = table.missed(target, e)
                    except Exception as e2:
                        log.warning("%s %s: %s", case_id, target, e2)
                        failures += 1
                        refresh(target)
                        continue
                elif e.status == 422:
                    log.warning("%s %s: message refused (%s) - planned move", case_id, target, e.detail)
                    try:
                        reply = send_safe(target, agent.fallback(case, view, target, plain=True)["message"])
                    except Exception as e2:
                        log.warning("%s %s: planned move failed too: %s", case_id, target, e2)
                        failures += 1
                        refresh(target)
                        continue
                else:
                    log.warning("%s %s: %s", case_id, target, e)
                    failures += 1
                    refresh(target)
                    continue
            except Exception as e:
                log.warning("%s %s: send failed: %s", case_id, target, e)
                failures += 1
                refresh(target)
                continue
            finally:
                inflight[target] = False
            failures = 0
            reply_at[target] = time.monotonic()
            agent.replied(target)
            if "result" in reply:
                with close_lock:
                    out.setdefault("result", reply["result"])
                    done.set()
                return
            reply = safe_documents(table, reply)
            with lock:
                threads[target] += [{**msg, "from": "buyer", **({"undelivered": True} if late else {})}, reply]
                slowest[0] = max(slowest[0], time.monotonic() - t0)
            log.info("%s %s %s %s", case_id, target, reply.get("status"),
                     (reply.get("term_sheets") or [{}])[0].get("terms"))  # fmt: skip

    live = live_threads(threads)
    if len(live) > 1:
        live = sorted(live, key=lambda s: agent.standing_cost(case, threads, s))
    workers = [threading.Thread(target=worker, args=(sid, rank), daemon=True) for rank, sid in enumerate(live)]
    for w in workers:
        w.start()
    for w in workers:
        w.join()
    if not done.is_set():  # every worker stopped without closing: the best the arena still holds
        for sid in list(threads):
            refresh(sid)
        with lock:
            view = copy.deepcopy(threads)
        if live_threads(view):
            d = agent.final_close(case, view)
            close(d)
    result = out.get("result") or table.result()
    agent.finish(result)
    return result

